default void appendTooltips(@NotNull List<Component> tooltip, boolean showToolsInfo, boolean showTemperatureInfo) {
        if (GTUtil.isShiftDown()) {
            if (showTemperatureInfo)
                tooltip.add(Component.translatable("gtceu.fluid_pipe.max_temperature",
                        FormattingUtil.formatTemperature(getMaxFluidTemperature())));
            if (isGasProof()) tooltip.add(Component.translatable("gtceu.fluid_pipe.gas_proof"));
            else tooltip.add(Component.translatable("gtceu.fluid_pipe.not_gas_proof"));
            if (isPlasmaProof()) tooltip.add(Component.translatable("gtceu.fluid_pipe.plasma_proof"));
            if (isCryoProof()) tooltip.add(Component.translatable("gtceu.fluid_pipe.cryo_proof"));
            getContainedAttributes().forEach(a -> a.appendContainerTooltips(tooltip::add));
        } else if (isGasProof() || isCryoProof() || isPlasmaProof() || !getContainedAttributes().isEmpty()) {
            if (showToolsInfo) {
                tooltip.add(Component.translatable("gtceu.tooltip.tool_fluid_hold_shift"));
            } else {
                tooltip.add(Component.translatable("gtceu.tooltip.fluid_pipe_hold_shift"));
            }
        }
    }

protected void addPrimaryDisplayItems(List<ItemElement> displayTools, MaterialVariantId materialId) {
    IMaterial material = getMaterial();
    // part builder
    if (allowPartBuilder() && material.isCraftable()) {
      ItemStack partBuilder = new ItemStack(TinkerTables.partBuilder.asItem());
      ItemElement elementItem = new TinkerItemElement(partBuilder);
      elementItem.tooltip = PART_BUILDER;
      displayTools.add(elementItem);
    }

    // regular casting recipes
    if (allowCasting()) {
      List<MaterialFluidRecipe> fluids = MaterialCastingLookup.getCastingFluids(materialId);
      if (!fluids.isEmpty()) {
        // get a list of all fluids from just visible recipes
        List<FluidStack> filtered = fluids.stream().filter(r -> !r.isHideInBook()).flatMap(recipe -> recipe.getFluids().stream()).toList();
        if (!filtered.isEmpty()) {
          ItemElement elementItem = new TinkerItemElement(0, 0, 1, filtered.stream().map(fluid -> new ItemStack(fluid.getFluid().getBucket())).toList());
          elementItem.tooltip = List.of(
            CASTABLE,
            Component.translatable(CAST_FROM, filtered.get(0).getDisplayName()).withStyle(ChatFormatting.GRAY)
          );
          displayTools.add(elementItem);
        }
      }

      // composite casting
      List<MaterialFluidRecipe> composites = MaterialCastingLookup.getCompositeFluids(materialId);
      for (MaterialFluidRecipe composite : composites) {
        MaterialVariant input = composite.getInput();
        if (!composite.isHideInBook() && input != null && !materialVariant.matchesVariant(input.getVariant())) {
          MaterialVariantId inputId = input.getVariant();
          // TODO: filter out tool parts that cannot be casted due to a composite cast conflict
          List<ItemStack> compositeParts = MaterialCastingLookup.getAllItemCosts().stream()
            .map(Entry::getKey)
            .filter(part -> part.canUseMaterial(inputId.getId()) && part.canUseMaterial(material) && (!(part instanceof IToolPart toolPart) || supportsStatType(toolPart.getStatType())))
            .map(part -> part.withMaterial(inputId))
            .toList();
          if (!compositeParts.isEmpty()) {
            ItemElement elementItem = new TinkerItemElement(0, 0, 1, compositeParts);
            FluidStack firstFluid = composite.getFluids().stream().findFirst().orElse(FluidStack.EMPTY);
            elementItem.tooltip = List.of(
              COMPOSITE,
              Component.translatable(COMPOSITE_FROM, firstFluid.getDisplayName(), MaterialTooltipCache.getDisplayName(inputId)).withStyle(ChatFormatting.GRAY)
            );
            displayTools.add(elementItem);
          }
        }
      }
    }
  }

public static void onKeyPressed(int action) {
		Minecraft mc = Minecraft.getInstance();
		while (JadeKeys.openConfig().consumeClick()) {
			Jade.invalidateConfig();
			ItemStorageProvider.targetCache.invalidateAll();
			ItemStorageProvider.containerCache.invalidateAll();
			mc.gui.setScreen(new HomeConfigScreen(null));
		}

		while (JadeKeys.showOverlay().consumeClick()) {
			IWailaConfig.General general = IWailaConfig.get().general();
			DisplayMode mode = general.getDisplayMode();
			if (mode == DisplayMode.TOGGLE) {
				general.setDisplayTooltip(!general.shouldDisplayTooltip());
				if (!general.shouldDisplayTooltip() && Jade.history().hintOverlayToggle) {
					mc.gui.chatListener().handleSystemMessage(Component.translatable("toast.jade.toggle_hint.1"), false);
					mc.gui.chatListener().handleSystemMessage(
							Component.translatable(
									"toast.jade.toggle_hint.2",
									JadeKeys.showOverlay().getTranslatedKeyMessage()), false);
					Jade.history().hintOverlayToggle = false;
				}
				narrateKey("show_overlay", general.shouldDisplayTooltip());
				IWailaConfig.get().save();
			}
		}

		while (JadeKeys.toggleLiquid().consumeClick()) {
			IWailaConfig.General general = IWailaConfig.get().general();
			general.setDisplayFluids(!general.shouldDisplayFluids());
			narrateKey("toggle_liquid", general.shouldDisplayFluids());
			IWailaConfig.get().save();
		}

		while (JadeKeys.narrate().consumeClick()) {
			IWailaConfig.Accessibility accessibility = IWailaConfig.get().accessibility();
			if (accessibility.getTTSMode() == TTSMode.TOGGLE) {
				accessibility.toggleTTS();
				if (accessibility.shouldEnableTextToSpeech() && Jade.history().hintNarratorToggle) {
					mc.gui.chatListener().handleSystemMessage(Component.translatable("toast.jade.tts_hint.1"), false);
					mc.gui.chatListener().handleSystemMessage(
							Component.translatable(
									"toast.jade.tts_hint.2",
									JadeKeys.narrate().getTranslatedKeyMessage()), false);
					Jade.history().hintNarratorToggle = false;
				}
				IWailaConfig.get().save();
			} else if (tickHandler.rootElement != null) {
				tickHandler.narrate(tickHandler.rootElement, false);
			}
		}

		if (Jade.rootConfig().isEnableProfiles()) {
			for (int i = 0; i < 4; i++) {
				while (profiles[i].consumeClick()) {
					Jade.useProfile(i);
					if (IWailaConfig.get().accessibility().getNarrateKeys()) {
						tickHandler.narrate(I18n.get("narration.jade.key.profile", profiles[i].getName()), false);
					}
				}
			}
		}

		while (JadeKeys.showUses().consumeClick()) {
			lookupRecipes(true, getLookupItemStack());
		}

		while (JadeKeys.showRecipes().consumeClick()) {
			lookupRecipes(false, getLookupItemStack());
		}
	}

