                this.r = r;
            }

            public T getLeft() {
                return t;
            }

            public R getRight() {
                return r;
            }

            @Override
            public boolean equals(Object o) {
                if (this == o) return true;
                if (o == null || getClass() != o.getClass()) return false;

                Pair<?, ?> pair = (Pair<?, ?>) o;

                if (!Objects.equals(t, pair.t)) return false;
                return Objects.equals(r, pair.r);
            }

            @Override
