public Component getIngredientTypeSortOrderValueName(String value) {
		String typeName = getSimpleClassName(value);
		IIngredientManager ingredientManager = runtime.getIngredientManager();
		Optional<Identifier> pluginUid = ingredientManager.getRegisteredIngredientTypes().stream()
			.filter(type -> IngredientTypeSortingConfig.getIngredientTypeString(type).equals(value))
			.findFirst()
			.flatMap(ingredientManager::getRegisteringPluginUid);
		if (pluginUid.isPresent()) {
			String modName = runtime.getJeiHelpers().getModIdHelper()
				.getModNameForModId(pluginUid.get().getNamespace());
			return Component.translatable("jei.config.client.sorting.ingredientTypeSortOrder.value", typeName, modName);
		}
		return Component.literal(typeName);
	}

@Override
    public List<Widget> setupDisplay(DefaultCompostingDisplay display, Rectangle bounds) {
        List<Widget> widgets = Lists.newArrayList();
        Point startingPoint = new Point(bounds.x + bounds.width - 55, bounds.y + 110);
        List<EntryIngredient> stacks = new ArrayList<>(display.getInputEntries());
        widgets.add(Widgets.createRecipeBase(bounds));
        int i = 0;
        for (int y = 0; y < 5; y++)
            for (int x = 0; x < 7; x++) {
                EntryIngredient entryIngredient = stacks.size() > i ? stacks.get(i) : EntryIngredient.empty();
                if (!entryIngredient.isEmpty() && entryIngredient.get(0).getType() == VanillaEntryTypes.ITEM) {
                    ItemStack firstStack = entryIngredient.get(0).castValue();
                    float chance = ComposterBlock.COMPOSTABLES.getFloat(firstStack.getItem());
                    if (chance > 0.0f) {
                        entryIngredient = entryIngredient.map(stack -> stack.copy().tooltip(Component.translatable("text.rei.composting.chance", Mth.clamp(Mth.floor(chance * 100), 0, 100)).withStyle(ChatFormatting.YELLOW)));
                    }
                }
                widgets.add(Widgets.createSlot(new Point(bounds.getCenterX() - 72 + 9 + x * 18, bounds.y + 12 + y * 18)).entries(entryIngredient).markInput());
                i++;
