@Override
	@NotNull
	public List<Component> getTooltipStrings(SequencedAssemblyRecipe recipe, IRecipeSlotsView iRecipeSlotsView, double mouseX, double mouseY) {
		List<Component> tooltip = new ArrayList<>();

		MutableComponent junk = CreateLang.translateDirect("recipe.assembly.junk");

		boolean singleOutput = recipe.getOutputChance() == 1;
		boolean willRepeat = recipe.getLoops() > 1;

		int xOffset = -7;
		int minX = 150 + xOffset;
		int maxX = minX + 18;
		int minY = 90;
		int maxY = minY + 18;
		if (!singleOutput && mouseX >= minX && mouseX < maxX && mouseY >= minY && mouseY < maxY) {
			float chance = recipe.getOutputChance();
			tooltip.add(junk);
			tooltip.add(chanceComponent(1 - chance));
			return tooltip;
		}

		minX = 55 + xOffset;
		maxX = minX + 65;
		minY = 92;
		maxY = minY + 24;
		if (willRepeat && mouseX >= minX && mouseX < maxX && mouseY >= minY && mouseY < maxY) {
			tooltip.add(CreateLang.translateDirect("recipe.assembly.repeat", recipe.getLoops()));
			return tooltip;
		}

		if (mouseY > 5 && mouseY < 84) {
			int width = 0;
			int margin = 3;
			for (SequencedRecipe<?> sequencedRecipe : recipe.getSequence())
				width += getSubCategory(sequencedRecipe).getWidth() + margin;
			width -= margin;
			xOffset = width / 2 + getBackground().getWidth() / -2;

			double relativeX = mouseX + xOffset;
			List<SequencedRecipe<?>> sequence = recipe.getSequence();
			for (int i = 0; i < sequence.size(); i++) {
				SequencedRecipe<?> sequencedRecipe = sequence.get(i);
				SequencedAssemblySubCategory subCategory = getSubCategory(sequencedRecipe);
				if (relativeX >= 0 && relativeX < subCategory.getWidth()) {
					tooltip.add(CreateLang.translateDirect("recipe.assembly.step", i + 1));
					tooltip.add(sequencedRecipe.getAsAssemblyRecipe()
						.getDescriptionForAssembly()
						.plainCopy()
						.withStyle(ChatFormatting.DARK_GREEN));
					return tooltip;
				}
				relativeX -= subCategory.getWidth() + margin;
			}
		}

		return tooltip;
	}

public EditConfigScreen(EditableConfigGroup configGroup, boolean readOnly) {
        super();

        this.readOnly = readOnly;
        group = configGroup;
        MutableComponent baseTitle = configGroup.getName().copy().withStyle(ChatFormatting.BOLD);
        title = readOnly ? baseTitle.append(" (").append(Component.translatable("ftblibrary.read_only")).append(")") : baseTitle;
        allConfigButtons = new ArrayList<>();

        List<EditableConfigValue<?>> list = new ArrayList<>();
        collectAllConfigValues(group, list);

        if (!list.isEmpty()) {
            ConfigGroupButton group = null;

            for (var value : list) {
                if (group == null || group.group != value.getGroup()) {
                    allConfigButtons.add(new VerticalSpaceWidget(mainPanel, 4));
                    group = new ConfigGroupButton(mainPanel, value.getGroup());
                    allConfigButtons.add(group);
                    groupSize++;
                }

                ConfigEntryButton<?> btn = new ConfigEntryButton<>(mainPanel, group, value);
                allConfigButtons.add(btn);
            }

            if (groupSize == 1) {
                allConfigButtons.remove(group);
            }
        }

        buttonExpandAll = new SimpleButton(topPanel, List.of(Component.translatable("gui.expand_all"), hotkeyTooltip("="), hotkeyTooltip("+")), Icons.EXPAND,
                (_, _) -> toggleAll(false));
        buttonCollapseAll = new SimpleButton(topPanel, List.of(Component.translatable("gui.collapse_all"), hotkeyTooltip("-")), Icons.COLLAPSE,
                (_, _) -> toggleAll(true));
    }

@Override
    public List<Component> getRecipeViewerTooltips(MultiPredicate root) {
        List<Component> tooltips = new ArrayList<>(this.getAdditionalTooltips());
        int minCount = getMinCount();
        int maxCount = getMaxCount();
        if (minCount == maxCount && maxCount != -1) {
            tooltips.add(Component.translatable("gtceu.multiblock.pattern.exact_count", minCount));
        } else if (minCount != maxCount && minCount != -1 && maxCount != -1) {
            tooltips.add(Component.translatable("gtceu.multiblock.pattern.between_count", minCount, maxCount));
        } else {
            if (minCount > 0) {
                tooltips.add(Component.translatable("gtceu.multiblock.pattern.min_count", minCount));
            }
            if (maxCount != -1) {
                tooltips.add(Component.translatable("gtceu.multiblock.pattern.max_count", maxCount));
            }
        }
        if (root.isSingle()) {
            tooltips.add(Component.translatable("gtceu.multiblock.pattern.single"));
        }
        if (root.hasAir()) {
            tooltips.add(Component.translatable("gtceu.multiblock.pattern.replaceable_air"));
        }
        return tooltips;
    }

