@Override
		public void renderHUD(GuiGraphics gui, Minecraft mc) {
			ItemStack stack = hourglass.getItemHandler().getItem(0);
			if (!stack.isEmpty()) {
				int x = mc.getWindow().getGuiScaledWidth() / 2 + 8;
				int y = mc.getWindow().getGuiScaledHeight() / 2 - 10;

				String first, second;
				if (hourglass.isDust()) {
					first = Integer.toString(hourglass.time);
					second = Integer.toString(hourglass.getTotalTime());
				} else {
					first = StringUtil.formatTickDuration(hourglass.time);
					second = StringUtil.formatTickDuration(hourglass.getTotalTime());
				}
				String timer = String.format("%s / %s", first, second);

				String status = hourglass.lock ? "locked" : "";
				if (!hourglass.move) {
					status = status.isEmpty() ? "stopped" : "lockedStopped";
				}
				if (!status.isEmpty()) {
					status = I18n.get("botaniamisc." + status);
				}

				int textWidth = Math.max(mc.font.width(timer), mc.font.width(status));

				RenderHelper.renderHUDBox(gui, x, y, x + textWidth + 24, y + 22);

				gui.renderFakeItem(stack, x + 2, y + 3);
				gui.renderItemDecorations(mc.font, stack, x + 2, y + 3);

				gui.drawString(mc.font, timer, x + 22, y + 2, hourglass.getColor());
				if (!status.isEmpty()) {
					gui.drawString(mc.font, status, x + 22, y + 12, hourglass.getColor());
				}
			}
		}

private void makeErrorTooltip() {
		Throwable e = book.getContents().getException();

		List<Component> lines = new ArrayList<>();
		while (e != null) {
			String msg = e.getMessage();
			if (msg != null && !msg.isEmpty()) {
				lines.add(Component.literal(e.getMessage()));
			}
			e = e.getCause();
		}

		if (!lines.isEmpty()) {
			lines.add(Component.translatable("patchouli.gui.lexicon.loading_error_log").withStyle(ChatFormatting.GREEN));
			setTooltip(lines);
		}
	}

private void clicc() {
            ImmutableSet<String> buttons = ImmutableSet.of(
                    I18n.get("gui.back"),
                    I18n.get("gui.done"),
                    I18n.get("gui.cancel"),
                    I18n.get("gui.toTitle"),
                    I18n.get("gui.toMenu"),
                    I18n.get("quark.gui.config.save"));

            // Iterate this way to ensure we match the more important back buttons first
            for (String b : buttons)
                for (GuiEventListener listener : listeners) {
                    if (listener instanceof Button w) {
                        if (w.getMessage().getString().equals(b) && w.visible && w.active) {
                            w.onClick(0, 0);
                            return;
                        }
                    }
                }

            Minecraft mc = Minecraft.getInstance();
            if (mc.level != null && mc.screen != null)
                mc.screen.onClose();
        }

