public static void makeTooltip(ZGatherTooltipComponents event) {
		ItemStack stack = event.getItemStack();
		if(SimilarBlockTypeHandler.isShulkerBox(stack) && stack.has(DataComponents.CONTAINER)) {
			ItemContainerContents contents = stack.get(DataComponents.CONTAINER);
			if (contents.nonEmptyStream().toList().isEmpty()) {
				return;
			}

			ClientPacketListener listener = Minecraft.getInstance().getConnection();
			List<Either<FormattedText, TooltipComponent>> tooltip = event.getTooltipElements();
			List<Either<FormattedText, TooltipComponent>> tooltipCopy = new ArrayList<>(tooltip);

			for(int i = 1; i < tooltipCopy.size(); i++) {
				Either<FormattedText, TooltipComponent> either = tooltipCopy.get(i);
				if(either.left().isPresent() && either.left().get() instanceof MutableComponent component) {
					String s = either.left().get().getString();
					if (component.getContents() instanceof TranslatableContents translatableContents && translatableContents.getKey().contains("container.shulkerBox"))
						tooltip.remove(either);
				}
			}

			if(!ImprovedTooltipsModule.shulkerBoxRequireShift || Screen.hasShiftDown())
				tooltip.add(1, Either.right(new ShulkerComponent(stack)));
			if(ImprovedTooltipsModule.shulkerBoxRequireShift && !Screen.hasShiftDown())
				tooltip.add(1, Either.left(Component.translatable("quark.misc.shulker_box_shift")));
		}
	}

protected void updateSearch() {
        String searchString = searchField.getValue().trim();
        if (searchField.getValue().isEmpty()) {
            searchField.setSuggestion(Component.translatable("ars_nouveau.spell_book_gui.search").getString());
        } else {
            searchField.setSuggestion("");
        }

        if (refreshItemList || !searchLast.equals(searchString)) {
            this.itemsSorted = new ArrayList<>();
            String search = searchString.toLowerCase();

            SearchType searchFieldType = SearchType.ITEM;
            for (SearchType value : SearchType.values()) {
                if (value.isMatch(search)) {
                    searchFieldType = value;
                }
            }
            if (searchFieldType != SearchType.ITEM) {
                search = searchString.substring(1);
            }
            String finalSearch = search;

            for (StoredItemStack stored : this.itemsUnsorted) {
                if (stored == null || stored.getStack() == null) continue;

                boolean isMatch = switch (searchFieldType) {
                    case ITEM -> {
                        boolean contains = stored.getStack().getHoverName().getString().toLowerCase().contains(finalSearch);
                        if (contains) yield true;
                        yield tooltipCache.getUnchecked(stored).stream().anyMatch(tooltip -> tooltip.toLowerCase().contains(finalSearch));
                    }
                    case MOD ->
                            BuiltInRegistries.ITEM.getKey(stored.getStack().getItem()).getNamespace().contains(finalSearch);
                    case TAG -> tagCache.getUnchecked(stored).stream().anyMatch(tag -> tag.contains(finalSearch));
                    case COMPONENT -> {
                        if (stored.getStack().getComponentsPatch().isEmpty()) yield false;
                        yield componentCache.getUnchecked(stored).contains(finalSearch);
                    }
                };

                if (isMatch) {
                    addStackToClientList(stored);
                }
            }

            Collections.sort(this.itemsSorted, noSort ? sortComp : comparator);
            if (!searchLast.equals(searchString)) {
                this.scrollTo(0);
                this.currentScroll = 0;
                if (searchType == 1) {
                    IAutoFillTerminal.sync(searchString);
                }
                Networking.sendToServer(new ClientSearchPacket(searchString));
                onUpdateSearch(searchString);
            } else {
                this.scrollTo(this.currentScroll);
            }
            refreshItemList = false;
            this.searchLast = searchString;
        }
    }

public void recalculateTree() {
		help = new Bounds(width - 18, height - 18, 16, 16);
		if (BoM.tree != null) {
			TreeVolume volume = addNewNodes(BoM.tree.goal, BoM.tree.batches, 1, 0, ChanceState.DEFAULT);
			nodes = volume.nodes;
			int horizontalOffset = (volume.getMaxRight() + volume.getMinLeft()) / 2;
			for (Node node : volume.nodes) {
				node.x -= horizontalOffset;
			}
			if (!volume.nodes.isEmpty()) {
				Node node = volume.nodes.get(0);
				int width = textRenderer.getWidth("x" + BoM.tree.batches);
				batches = new Bounds(node.x + node.width / 2 + 6, node.y - 10, width + 12, 22);
			}

			nodeWidth = volume.getMaxRight() - volume.getMinLeft();
			nodeHeight = getNodeHeight(BoM.tree.goal);
			playerInv = EmiPlayerInventory.of(client.player);
			BoM.tree.calculateProgress(playerInv);
			Map<EmiIngredient, FlatMaterialCost> progressCosts = BoM.tree.cost.costs.values().stream()
				.collect(Collectors.toMap(c -> c.ingredient, c -> c));
			Map<EmiIngredient, ChanceMaterialCost> chanceProgressCosts = BoM.tree.cost.chanceCosts.values().stream()
				.collect(Collectors.toMap(c -> c.ingredient, c -> c));

			costs.clear();
			BoM.tree.calculateCost();

			List<FlatMaterialCost> treeCosts = Stream.concat(
				BoM.tree.cost.costs.values().stream(),
				BoM.tree.cost.chanceCosts.values().stream()
			).sorted((a, b) -> Integer.compare(
				EmiStackList.getIndex(a.ingredient.getEmiStacks().get(0)),
				EmiStackList.getIndex(b.ingredient.getEmiStacks().get(0))
			)).toList();
			int cy = nodeHeight * NODE_VERTICAL_SPACING * 2;
			int costX = 0;
			for (FlatMaterialCost node : treeCosts) {
				Cost cost = new Cost(node, costX, cy, false);
				if (BoM.craftingMode) {
					if (node instanceof ChanceMaterialCost cmc) {
						if (!chanceProgressCosts.containsKey(node.ingredient)) {
							cost.alreadyDone = node.getEffectiveAmount();
						} else {
							ChanceMaterialCost progress = chanceProgressCosts.get(node.ingredient);
							cost.alreadyDone = (long) Math.ceil(cmc.amount * cmc.chance - progress.amount * progress.chance);
						}
					} else {
						if (!progressCosts.containsKey(node.ingredient)) {
							cost.alreadyDone = node.amount;
						} else {
							FlatMaterialCost progress = progressCosts.get(node.ingredient);
							cost.alreadyDone = node.amount - progress.amount;
						}
					}
				}
				costs.add(cost);
				costX += 16 + COST_HORIZONTAL_SPACING + EmiRenderHelper.getAmountOverflow(cost.getAmountText());
			}
			int costOffset = (costX - COST_HORIZONTAL_SPACING) / 2;
			for (Cost cost : costs) {
				cost.x -= costOffset;
			}

			int totalCostWidth = textRenderer.getWidth(EmiPort.translatable("emi.total_cost"));
			mode = new Bounds(totalCostWidth / 2 + 4, cy - 20, 16, 16);

			List<Cost> remainders = Lists.newArrayList();

			List<FlatMaterialCost> remainderCosts = Stream.concat(
				BoM.tree.cost.remainders.values().stream(),
				BoM.tree.cost.chanceRemainders.values().stream()
			).sorted((a, b) -> Integer.compare(
				EmiStackList.getIndex(a.ingredient.getEmiStacks().get(0)),
				EmiStackList.getIndex(b.ingredient.getEmiStacks().get(0))
			)).toList();
			cy += 40;
			int remainderX = 0;
			for (FlatMaterialCost node : remainderCosts) {
				if (node.getEffectiveAmount() <= 0) {
					continue;
				}
				Cost cost = new Cost(node, remainderX, cy, true);
				remainders.add(cost);
				remainderX += 16 + COST_HORIZONTAL_SPACING + EmiRenderHelper.getAmountOverflow(cost.getAmountText());
			}
			costOffset = (remainderX - COST_HORIZONTAL_SPACING) / 2;
			for (Cost cost : remainders) {
				cost.x -= costOffset;
			}
			costs.addAll(remainders);
			hasRemainders = !remainders.isEmpty();
		} else {
			nodes = Lists.newArrayList();
		}
		batcher.repopulate();
	}

