private static Component defaultStringToComponent(String s) {
        if (s.isEmpty()) {
            return Component.empty();
        }

        if (s.indexOf(':') != -1) {
            var map = StringUtils.splitProperties(s);

            for (var parser : CUSTOM_COMPONENT_PARSERS) {
                var c = parser.parse(s, map);

                if (c != null && c != Component.EMPTY) {
                    return c;
                }
            }

            if (map.containsKey("image")) {
                var c = ImageComponent.create(map.get("image"),
                        Integer.parseInt(map.getOrDefault("width", "100")),
                        Integer.parseInt(map.getOrDefault("height", "100")),
                        ImageComponent.ImageAlign.byName(map.getOrDefault("align", "center")),
                        map.getOrDefault("fit", "false").equals("true"),
                        map.getOrDefault("click_action", "")
                );
                var output = MutableComponent.create(c);
                if (map.containsKey("text")) {
                    output.withStyle(Style.EMPTY.withHoverEvent(new HoverEvent.ShowText(parse(map.get("text")))));
                }

                return output;
            } else if (map.containsKey("open_url")) {
                return parse(map.get("text")).copy().withStyle(Style.EMPTY.withClickEvent(new ClickEvent.OpenUrl(URI.create(map.get("open_url")))));
            }
        }

        return parse(I18n.get(s));
    }

public static void appendFluidTooltips(FluidStack fluidStack, Consumer<Component> tooltips, TooltipFlag flag) {
        Fluid fluid = fluidStack.getFluid();
        int amount = fluidStack.getAmount();
        FluidType fluidType = fluid.getFluidType();

        if (fluidType == GTFluids.POTION.getType()) {
            if (fluid.is(FluidTags.WATER)) {
                return;
            }
            PotionFluidHelper.addPotionTooltip(fluidStack, tooltips);
            return;
        }

        var material = ChemicalHelper.getMaterial(fluid);
        if (material != null) {
            if (material.requiresMetalFreezing() && fluid.isSame(material.getFluid(FluidStorageKeys.LIQUID))) {
                tooltips.accept(Component.translatable("gtceu.fluid.requires_metal_freezing")
                        .withStyle(ChatFormatting.GOLD));
            }
            var formula = material.getChemicalFormula();
            if (formula != null && !formula.isEmpty()) {
                tooltips.accept(Component.literal(formula).withStyle(ChatFormatting.YELLOW));
            }

            if (material.hasProperty(PropertyKey.INGOT)) {
                if (GTUtil.isShiftDown() && amount >= GTValues.L) {
                    long ingots = amount / GTValues.L;
                    long remainder = amount % GTValues.L;
                    String fluidAmount = String.format(" %,d mB = %,d * %d mB", amount, ingots, GTValues.L);
                    if (remainder != 0) {
                        fluidAmount += String.format(" + %d mB", remainder);
                    }
                    tooltips.accept(Component.translatable("gtceu.gui.fluid_amount").withStyle(ChatFormatting.GRAY)
                            .append(Component.literal(fluidAmount)));
                }
            }
        }

        if (fluid instanceof GTFluid attributedFluid) {
            FluidState state = attributedFluid.getState();
            switch (state) {
                case LIQUID -> tooltips.accept(Component.translatable("gtceu.fluid.state_liquid"));
                case GAS -> tooltips.accept(Component.translatable("gtceu.fluid.state_gas"));
                case PLASMA -> tooltips.accept(Component.translatable("gtceu.fluid.state_plasma"));
            }
            attributedFluid.getAttributes().forEach(a -> a.appendFluidTooltips(tooltips));
        } else {
            String key = "gtceu.fluid.state_" + (fluidType.isLighterThanAir() ? "gas" : "liquid");
            tooltips.accept(Component.translatable(key));
        }

        tooltips.accept(Component.translatable("gtceu.fluid.temperature",
                FormattingUtil.formatTemperature(fluidType.getTemperature())));
        if (fluidType.getTemperature() < FluidConstants.CRYOGENIC_FLUID_THRESHOLD) {
            tooltips.accept(Component.translatable("gtceu.fluid.temperature.cryogenic"));
        }
    }

public static Component getMaterialName(MaterialVariantId material, String suffix) {
    // first, try the material directly
    String materialKey = MaterialTooltipCache.getKey(material) + '.' + suffix;
    if (Util.canTranslate(materialKey)) {
      return Component.translatable(materialKey);
    }
    // if that did not work, do base material
    if (material.hasVariant()) {
      materialKey = MaterialTooltipCache.getKey(material.getId()) + '.' + suffix;
      if (Util.canTranslate(materialKey)) {
        return Component.translatable(materialKey);
      }
    }
    // if both failed, use the regular key
    return MaterialTooltipCache.getDisplayName(material);
  }

@Override
		public void appendTooltip(ITooltip tooltip, T accessor, IPluginConfig config) {
			if (!accessor.showDetails() && config.get(JadeIds.UNIVERSAL_FLUID_STORAGE_DETAILED)) {
				return;
			}

			List<ClientViewGroup<FluidView>> groups = ClientProxy.mapToClientGroups(
					accessor,
					JadeIds.UNIVERSAL_FLUID_STORAGE,
					STREAM_CODEC,
					WailaClientRegistration.instance().fluidStorageProviders::get,
					tooltip);
			if (groups == null || groups.isEmpty()) {
				return;
			}

			boolean renderGroup = groups.size() > 1 || groups.getFirst().shouldRenderGroup();
			ClientViewGroup.tooltip(
					tooltip, groups, renderGroup, (theTooltip, group) -> {
						if (renderGroup) {
							group.renderHeader(theTooltip);
						}
						for (var view : group.views) {
							Component text;
							IWailaConfig.HandlerDisplayStyle style = config.getEnum(JadeIds.UNIVERSAL_FLUID_STORAGE_STYLE);

							if (view.overrideText != null) {
								text = view.overrideText;
							} else if (view.fluidName == null) {
								// when do we reach here?
								text = NarratableComponent.attach(IThemeHelper.get().info(view.current), view.current);
							} else {
								Component fluidAmount;
								Component fluidName = IThemeHelper.get().info(IDisplayHelper.get().stripColor(view.fluidName));
								if (accessor.showDetails() || style != IWailaConfig.HandlerDisplayStyle.PROGRESS_BAR) {
									fluidAmount = new NarratableComponent(
											Component.translatable(
													"jade.fluid.with_capacity",
													IThemeHelper.get().info(view.current),
													view.max), () -> JadeClient.formatString(
											"narration.jade.withCapacity",
											NarratableComponent.getNarration(view.current),
											NarratableComponent.getNarration(view.max)));
								} else {
									fluidAmount = NarratableComponent.attach(IThemeHelper.get().info(view.current), view.current);
								}
								String key = style == IWailaConfig.HandlerDisplayStyle.PLAIN_TEXT ? "jade.fluid.text" : "jade.fluid";
								text = NarratableComponent.translatable(key, fluidName, fluidAmount);
							}

							switch (style) {
								case PLAIN_TEXT -> theTooltip.add(text);
								case ICON -> {
									theTooltip.add(JadeUI.smallItem(new ItemStack(Items.BUCKET)));
									theTooltip.append(text);
								}
								case PROGRESS_BAR -> {
									ProgressView progressView = new ProgressView(
											ProgressView.Part.of(view.ratio, view.overlay),
											text,
											JadeUI.progressStyle().canDecrease(true),
											BoxStyle.nestedBox());
									theTooltip.add(JadeUI.progress(progressView));
								}
							}
						}
						if (group.extraData != null) {
							int extra = group.extraData.getIntOr("+", 0);
							if (extra > 0) {
								theTooltip.add(Component.translatable("jade.fluid.more_tanks", extra));
							}
						}
					});
		}

