@Override
	protected void extractContents(GuiGraphicsExtractor graphics, int mouseX, int mouseY, float partialTicks) {
		if (!active) {
			return;
		}
		if (isHoveredOrFocused()) {
			timeHovered = Math.min(ANIM_TIME, timeHovered + ClientTicker.delta);
		} else {
			timeHovered = Math.max(0, timeHovered - ClientTicker.delta);
		}

		float time = Math.max(0, Math.min(ANIM_TIME, timeHovered + (isHoveredOrFocused() ? partialTicks : -partialTicks)));
		float widthFract = time / ANIM_TIME;
		boolean locked = entry.isLocked();

		graphics.pose().scale(0.5F, 0.5F);
		graphics.fill(getX() * 2, getY() * 2, (getX() + (int) ((float) width * widthFract)) * 2, (getY() + height) * 2, 0x22000000);
		//RenderSystem.enableBlend();

		if (locked) {
			//graphics.setColor(1F, 1F, 1F, 0.7F);
			GuiBook.drawLock(graphics, parent.book, getX() * 2 + 2, getY() * 2 + 2, ARGB.color(0.7F, 0xffffff));
		} else {
			entry.getIcon().extractRenderState(graphics, getX() * 2 + 2, getY() * 2 + 2);
		}

		graphics.pose().scale(2F, 2F);

		MutableComponent name;
		if (locked) {
			name = Component.translatable("patchouli.gui.lexicon.locked");
		} else {
			name = entry.getName();
			if (entry.isPriority()) {
				name = name.withStyle(ChatFormatting.ITALIC);
			}
		}

		name = name.withStyle(entry.getBook().getFontStyle());
		graphics.text(Minecraft.getInstance().font, name, getX() + 12, getY(), getColor(), false);

		if (!entry.isLocked()) {
			GuiBook.drawMarking(graphics, parent.book, getX() + width - 5, getY() + 1, entry.hashCode(), entry.getReadState());
		}
	}

@PlayEvent
		public void onDrawScreen(ZScreen.Render.Post event) {
			Minecraft mc = Minecraft.getInstance();
			Screen gui = mc.screen;
			GuiGraphics guiGraphics = event.getGuiGraphics();

			if(mc.player != null && gui instanceof AbstractContainerScreen<?> containerGui) {
				ItemStack held = containerGui.getMenu().getCarried();
				if(!held.isEmpty()) {
					Slot under = containerGui.getSlotUnderMouse();
					if(under == null || under instanceof AccessorCustomCreativeSlot)
						return;

					ItemStack underStack = under.getItem();

					int x = event.getMouseX();
					int y = event.getMouseY();
					if(enableLavaInteraction && canTrashItem(underStack, held, under, mc.player)) {
						guiGraphics.renderComponentTooltip(mc.font, List.of(Component.translatable(
								invertClicks ? "quark.misc.trash_item.invert" : "quark.misc.trash_item"
						).withStyle(ChatFormatting.RED)), x, y);
					} else if(enableShulkerBoxInteraction && tryAddToShulkerBox(mc.player, underStack, held, under, true, true, true) != null) {
						guiGraphics.renderComponentTooltip(mc.font, List.of(Component.translatable(
								SimilarBlockTypeHandler.isShulkerBox(held) ?
										invertClicks ? "quark.misc.merge_shulker_box.invert"  : "quark.misc.merge_shulker_box"
										:
										invertClicks ? "quark.misc.insert_shulker_box.invert" : "quark.misc.insert_shulker_box"
						).withStyle(ChatFormatting.YELLOW)), x, y, underStack);
					} else if(enableShulkerBoxInteraction && SimilarBlockTypeHandler.isShulkerBox(underStack)) {
						guiGraphics.renderComponentTooltip(mc.font, Screen.getTooltipFromItem(mc, underStack), x, y, underStack);
					}

				}
			}
		}

