@PlayEvent
		public void initGui(ZScreen.Init.Post event) {
			if(event.getScreen() instanceof ChatScreen) {
				emoteButtons.clear();

				Window window = Minecraft.getInstance().getWindow();
				int windowWidth = window.getGuiScaledWidth();
				int windowHeight = window.getGuiScaledHeight();

				Map<Integer, List<EmoteDescriptor>> descriptorSorting = new TreeMap<>();

				for(EmoteDescriptor desc : EmoteHandler.emoteMap.values()) {
					if(desc.getTier() <= ContributorRewardHandler.localPatronTier) {
						List<EmoteDescriptor> descriptors = descriptorSorting.computeIfAbsent(desc.getTier(), k -> new LinkedList<>());

						descriptors.add(desc);
					}
				}

				int rows = 0;
				int row = 0;
				int tierRow, rowPos;

				Minecraft mc = Minecraft.getInstance();
				boolean expandDown = mc.options.showSubtitles().get();

				Set<Integer> keys = descriptorSorting.keySet();
				for(int tier : keys) {
					List<EmoteDescriptor> descriptors = descriptorSorting.get(tier);
					if(descriptors != null) {
						rows += descriptors.size() / 3;
						if(descriptors.size() % 3 != 0)
							rows++;
					}
				}

				int buttonX = buttonShiftX;
				int buttonY = (expandDown ? 2 : windowHeight - 40) + buttonShiftY;

				for(int tier : keys) {
					rowPos = 0;
					tierRow = 0;
					List<EmoteDescriptor> descriptors = descriptorSorting.get(tier);
					if(descriptors != null) {
						for(EmoteDescriptor desc : descriptors) {
							int rowSize = Math.min(descriptors.size() - tierRow * EMOTES_PER_ROW, EMOTES_PER_ROW);

							int x = buttonX + windowWidth - 2 - (EMOTE_BUTTON_WIDTH * (EMOTES_PER_ROW + 1)) + (((rowPos + 1) * 2 + EMOTES_PER_ROW - rowSize) * EMOTE_BUTTON_WIDTH / 2 + 1);
							int y = buttonY + (EMOTE_BUTTON_WIDTH * (rows - row)) * (expandDown ? 1 : -1);

							NotButton button = new NotButton(
								x, y,
								EMOTE_BUTTON_WIDTH - 1, EMOTE_BUTTON_WIDTH - 1,
								desc,
								() -> PacketDistributor.sendToServer(new RequestEmoteMessage(desc.getRegistryName()))
							);

							emoteButtons.add(button);

							if(++rowPos == EMOTES_PER_ROW) {
								tierRow++;
								row++;
								rowPos = 0;
							}
						}
					}
					if(rowPos != 0)
						row++;
				}

				emoteToggleButton = new NotButton(
					buttonX + windowWidth - 2 - EMOTE_BUTTON_WIDTH * EMOTES_PER_ROW, buttonY,
					EMOTE_BUTTON_WIDTH * EMOTES_PER_ROW, 20,
					Component.translatable("quark.gui.button.emotes"),
					() -> emotesVisible ^= true
				);

				event.getScreen().renderables.add((gfx, mouseX, mouseY, partialTicks) -> {
					emoteToggleButton.draw(gfx, mouseX, mouseY, theMouseIsPressedNowThankYou);
					if(emotesVisible)
						for(NotButton b : emoteButtons)
							b.draw(gfx, mouseX, mouseY, theMouseIsPressedNowThankYou);
				});
			}
		}

public void onSearchChanged(String str) {
        previousString = str;
        if (!str.isEmpty()) {
            searchBar.setSuggestion("");
            displayedGlyphs = new ArrayList<>();

            for (RecipeHolder<GlyphRecipe> spellPart : allParts) {
                if (spellPart.value().getSpellPart().getLocaleName().toLowerCase().contains(searchBar.value.toLowerCase())) {
                    displayedGlyphs.add(spellPart);
                }
            }

            for (Renderable w : renderables) {
                if (w instanceof GlyphButton glyphButton) {
                    if (glyphButton.abstractSpellPart.getRegistryName() != null) {
                        AbstractSpellPart part = GlyphRegistry.getSpellpartMap().get(glyphButton.abstractSpellPart.getRegistryName());
                        if (part != null) {
                            glyphButton.visible = part.getLocaleName().toLowerCase().contains(searchBar.value.toLowerCase());
                        }
                    }
                }
            }
        } else {
            // Reset our book on clear
            searchBar.setSuggestion(Component.translatable("ars_nouveau.spell_book_gui.search").getString());
            displayedGlyphs = allParts;
            for (Renderable w : renderables) {
                if (w instanceof GlyphButton) {
                    ((GlyphButton) w).visible = true;
                }
            }
        }
        displayedGlyphs = applyFilter(displayedGlyphs);
        resetPageState();
    }

public static void render(EmiDrawContext context, int mouseX, int mouseY, float delta) {
		EmiProfiler.push("emi");
		updateMouse(mouseX, mouseY);
		recalculate();
		EmiScreenBase base = EmiScreenBase.getCurrent();
		if (base.isEmpty()) {
			EmiProfiler.pop();
			return;
		}
		boolean visible = !isDisabled();
		emi.visible = EmiConfig.emiConfigButtonVisibility.resolve(visible);
		tree.visible = EmiConfig.recipeTreeButtonVisibility.resolve(visible);
		for (SidebarPanel panel : panels) {
			panel.updateWidgetVisibility();
		}
		renderWidgets(context, mouseX, mouseY, delta, base);
		if (isDisabled()) {
			int screenHeight = base.screen().height;
			if (!EmiReloadManager.isLoaded()) {
				int reloadInfoX = getDebugTextX();
				if (EmiReloadManager.getStatus() == -1) {
					context.drawTextWithShadow(EmiPort.translatable("emi.reloading.error"), reloadInfoX, screenHeight - 16);
				} else if (EmiReloadManager.getStatus() == 0) {
					context.drawTextWithShadow(EmiPort.translatable("emi.reloading.waiting"), reloadInfoX, screenHeight - 16);
				} else {
					context.drawTextWithShadow(EmiPort.translatable("emi.reloading"), reloadInfoX, screenHeight - 16);
					context.drawTextWithShadow(EmiReloadManager.reloadStep, reloadInfoX, screenHeight - 26);
					if (System.currentTimeMillis() > EmiReloadManager.reloadWorry) {
						context.drawTextWithShadow(EmiPort.translatable("emi.reloading.worry"), reloadInfoX, screenHeight - 36);
					}
				}
			} else {
			}
			EmiProfiler.pop();
			lastHoveredCraftable = null;
			return;
		} else if (EmiRecipes.activeWorker != null) {
			int bakingX = getDebugTextX();
			context.drawTextWithShadow(EmiPort.translatable("emi.reloading.still_baking_recipes"), bakingX, base.screen().height - 16);
		} else {
			renderDevMode(context, mouseX, mouseY, delta, base);
		}
		EmiProfiler.push("sidebars");
		for (SidebarPanel panel : panels) {
			panel.render(context, mouseX, mouseY, delta);
		}

		renderLastHoveredCraftable(context, mouseX, mouseY, delta, base);

		EmiProfiler.pop();

		renderExclusionAreas(context, mouseX, mouseY, delta, base);

		EmiProfiler.swap("slots");
		renderSlotOverlays(context, mouseX, mouseY, delta, base);
		EmiProfiler.pop();

		context.disableDepthTest();
	}

