public WidgetGroup getWidgets(int x, int y, int availableWidth, int availableHeight) {
		int wx = x + (availableWidth - width) / 2;
		wx = Math.max(x + getLeftWidth(), Math.min(x + availableWidth - width - getRightWidth(), wx));
		int wy = y;
		int wWidth = width;
		int wHeight = Math.min(availableHeight, height);
		WidgetGroup widgets = new WidgetGroup(recipe, wx, wy, wWidth, wHeight);
		if (recipe != null) {
			try {
				recipe.addWidgets(widgets);
				if (EmiConfig.showRecipeDecorators) {
					for (EmiRecipeDecorator decorator : EmiRecipes.decorators) {
						decorator.decorateRecipe(recipe, widgets);
					}
				}
				if (EmiConfig.devMode) {
					widgets.decorateDevMode();
				}
				addButtons(widgets, leftButtons, 0 - 4 - 13, -14);
				addButtons(widgets, rightButtons, width + 5, 14);
			} catch (Throwable t) {
				EmiLog.error("Error constructing recipe widgets", t);
				widgets = new WidgetGroup(recipe, wx, wy, wWidth, wHeight);
				widgets.add(new TextWidget(EmiPort.ordered(EmiPort.translatable("emi.error.recipe.render")),
					wWidth / 2, wHeight / 2 - 5, Formatting.RED.getColorValue(), true).horizontalAlign(Alignment.CENTER));
				if (exception != null) {
					List<Text> text = EmiUtil.getStackTrace(exception).stream().map(s -> (Text) EmiPort.literal(s)).toList();
					widgets.addTooltipText(text, 0, 0, wWidth, wHeight);
				}
			}
		} else {
			widgets.add(new TextWidget(EmiPort.ordered(EmiPort.translatable("emi.error.recipe.initialize")),
				wWidth / 2, wHeight / 2 - 5, Formatting.RED.getColorValue(), true).horizontalAlign(Alignment.CENTER));
			if (exception != null) {
				List<Text> text = EmiUtil.getStackTrace(exception).stream().map(s -> (Text) EmiPort.literal(s)).toList();
				widgets.addTooltipText(text, 0, 0, wWidth, wHeight);
			}
		}
		return widgets;
	}

private void addCategories(EmiRegistry registry) {
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.CRYSTALLIZING, ChemicalCrystallizerEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.DISSOLUTION, ChemicalDissolutionEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.CHEMICAL_INFUSING, ChemicalChemicalToChemicalEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.WASHING, FluidChemicalToChemicalEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.SEPARATING, ElectrolysisEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.METALLURGIC_INFUSING, MetallurgicInfuserEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.REACTION, PressurizedReactionEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.PIGMENT_EXTRACTING, PigmentExtractingEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.PIGMENT_MIXING, PigmentMixerEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.PAINTING, PaintingEmiRecipe::new);

        //Register both methods of rotary condensentrator recipes
        MekanismEmiRecipeCategory condensentratingCategory = addCategory(registry, RecipeViewerRecipeType.CONDENSENTRATING);
        MekanismEmiRecipeCategory decondensentratingCategory = addCategory(registry, RecipeViewerRecipeType.DECONDENSENTRATING);
        //TODO - Emi: review recipe access when updating emi
        for (RecipeHolder<RotaryRecipe> recipeHolder : MekanismRecipeType.ROTARY.getRecipes(MekanismClient.clientRecipes())) {
            RotaryRecipe recipe = recipeHolder.value();
            if (recipe.hasChemicalToFluid()) {
                if (recipe.hasFluidToChemical()) {
                    //Note: If the recipe is bidirectional, we prefix the recipe id so that they don't clash as duplicates
                    // as we return the proper recipe holder regardless
                    registry.addRecipe(new RotaryEmiRecipe(condensentratingCategory, RegistryUtils.synthetic(recipeHolder.id(), "condensentrating"), recipeHolder, true));
                    registry.addRecipe(new RotaryEmiRecipe(decondensentratingCategory, RegistryUtils.synthetic(recipeHolder.id(), "decondensentrating"), recipeHolder, false));
                } else {
                    registry.addRecipe(new RotaryEmiRecipe(condensentratingCategory, recipeHolder.id().identifier(), recipeHolder, true));
                }
            } else if (recipe.hasFluidToChemical()) {
                registry.addRecipe(new RotaryEmiRecipe(decondensentratingCategory, recipeHolder.id().identifier(), recipeHolder, false));
            }
        }

        addCategoryAndRecipes(registry, RecipeViewerRecipeType.OXIDIZING, (category, recipeHolder) -> new ItemStackToChemicalEmiRecipe<>(category, recipeHolder, TileEntityChemicalOxidizer.BASE_TICKS_REQUIRED));

        addCategoryAndRecipes(registry, RecipeViewerRecipeType.NUTRITIONAL_LIQUIFICATION, (category, id, recipe) -> new ItemStackToFluidOptionalItemEmiRecipe(category, id, recipe, TileEntityNutritionalLiquifier.BASE_TICKS_REQUIRED), RecipeViewerUtils.getLiquificationRecipes());

        addCategoryAndRecipes(registry, RecipeViewerRecipeType.ACTIVATING, ChemicalToChemicalEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.CENTRIFUGING, ChemicalToChemicalEmiRecipe::new);

        addCategoryAndRecipes(registry, RecipeViewerRecipeType.COMBINING, CombinerEmiRecipe::new);

        addCategoryAndRecipes(registry, RecipeViewerRecipeType.PURIFYING, ItemStackChemicalToItemStackEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.COMPRESSING, ItemStackChemicalToItemStackEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.INJECTING, ItemStackChemicalToItemStackEmiRecipe::new);

        addCategoryAndRecipes(registry, RecipeViewerRecipeType.NUCLEOSYNTHESIZING, NucleosynthesizingEmiRecipe::new);

        //TODO - Emi: Figure out the registry access, maybe we can get it from the EmiRegistry
        HolderLookup.Provider registries = Objects.requireNonNull(getRegistryAccess());
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.SPS, SPSEmiRecipe::new, SPSRecipeViewerRecipe.getSPSRecipes(registries));
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.BOILER, BoilerEmiRecipe::new, BoilerRecipeViewerRecipe.getBoilerRecipes(registries));

        addCategoryAndRecipes(registry, RecipeViewerRecipeType.SAWING, SawmillEmiRecipe::new);

        addCategoryAndRecipes(registry, RecipeViewerRecipeType.ENRICHING, ItemStackToItemStackEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.CRUSHING, ItemStackToItemStackEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.SMELTING, ItemStackToItemStackEmiRecipe::new);

        addCategoryAndRecipes(registry, RecipeViewerRecipeType.EVAPORATING, FluidToFluidEmiRecipe::new);

        //Conversion recipes
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.ENERGY_CONVERSION, ItemStackToEnergyEmiRecipe::new);
        addCategoryAndRecipes(registry, RecipeViewerRecipeType.CHEMICAL_CONVERSION, (category, recipeHolder) -> new ItemStackToChemicalEmiRecipe<>(category, recipeHolder, 0));

        registry.addRecipe(new EmiInfoRecipe(List.of(EmiStack.of(MekanismFluids.HEAVY_WATER.value())), List.of(
              MekanismLang.RECIPE_VIEWER_INFO_HEAVY_WATER.translate(MekanismConfig.general.pumpHeavyWaterAmount.get())
        ), Mekanism.rl("info/heavy_water")));
        //TODO: Can we just add this to the base module item?
        registry.addRecipe(new EmiInfoRecipe(MekanismRegistries.MODULES.stream()
              .map(data -> IModuleHelper.INSTANCE.asStack(MekanismRegistries.MODULES.wrapAsHolder(data)))
              .<EmiIngredient>map(EmiStack::of)
              .toList(), List.of(
              MekanismLang.RECIPE_VIEWER_INFO_MODULE_INSTALLATION.translate()
        ), Mekanism.rl("info/module_installation")));
    }

@Override
	public void registerSlotDisplayInterpreters(ISlotDisplayInterpreterRegistration registration) {
		FireworkRocketRecipeCategoryExtension.registerSlotDisplayInterpreter(registration);
		registration.registerUniversal(SlotDisplay.Composite.TYPE, (slotDisplay, interpretationBuilder) -> {
			for (SlotDisplay childDisplay : slotDisplay.contents()) {
				interpretationBuilder.addChildDisplay(childDisplay);
			}
		});
		registration.register(SlotDisplay.ItemSlotDisplay.TYPE, (slotDisplay, ignoredContext, interpretationBuilder) -> {
			// A REFERENCE names only the item, so allow all its variants.
			// Otherwise (for DIRECT), keep the specified variants.
			interpretationBuilder.setWildcardForSubtypes(slotDisplay.item().kind() == Holder.Kind.REFERENCE);
		});
		registration.register(SlotDisplay.TagSlotDisplay.TYPE, (slotDisplay, ignoredContext, interpretationBuilder) -> {
			slotDisplay.tag()
				.unwrapKey()
				.ifPresent(interpretationBuilder::setTagKey);
			interpretationBuilder.setWildcardForSubtypes(true);
		});
		registration.register(SlotDisplay.AnyFuel.TYPE, (ignoredSlotDisplay1, ignoredContext, interpretationBuilder) -> {
			interpretationBuilder
				.setTooltipHeader(
					Component.translatable("jei.tooltip.recipe.any_fuel")
						.withStyle(ChatFormatting.GOLD)
						.withStyle(ChatFormatting.ITALIC)
				)
				.setWildcardForSubtypes(true);
		});
		registration.register(SlotDisplay.WithAnyPotion.TYPE, (ignoredSlotDisplay, context, interpretationBuilder) -> {
			List<ITypedIngredient<ItemStack>> ingredients = context.getIngredients();
			if (ingredients.isEmpty()) {
				return;
			}
			ItemStack itemStack = ingredients.getFirst().getIngredient();
			Component itemName = Component.translatable(itemStack.getItem().getDescriptionId());
			interpretationBuilder.setTooltipHeader(
				Component.translatable("jei.tooltip.recipe.any", itemName)
					.withStyle(ChatFormatting.GOLD)
					.withStyle(ChatFormatting.ITALIC)
			);
		});
		registration.register(SlotDisplay.WithRemainder.TYPE, (slotDisplay, ignoredContext, interpretationBuilder) -> {
			interpretationBuilder.addChildDisplay(slotDisplay.input());
		});
	}

public DefaultListEntry(CategoryRegistry.CategoryConfiguration<?> configuration) {
            this.configuration = configuration;
            {
                Component toggleText = Component.translatable("config.roughlyenoughitems.filtering.filteringQuickCraftCategories.configure.toggle");
                visibilityToggleButton = Widgets.createClickableLabel(new Point(), toggleText, $ -> {
                    boolean enabled = !hiddenCategories.contains(configuration.getCategoryIdentifier());
                    if (enabled) {
                        // set to false
                        hiddenCategories.add(configuration.getCategoryIdentifier());
                    } else {
                        // set to true
                        hiddenCategories.remove(configuration.getCategoryIdentifier());
                    }

                    editedSink.run();
                }).leftAligned();
                quickCraftToggleButton = Widgets.createClickableLabel(new Point(), toggleText, $ -> {
                    boolean quickCraftingEnabledByDefault = configuration.isQuickCraftingEnabledByDefault();
                    boolean enabled = filteringQuickCraftCategories.getOrDefault(configuration.getCategoryIdentifier(), quickCraftingEnabledByDefault);
                    if (enabled) {
                        // set to false
                        if (!quickCraftingEnabledByDefault) {
                            filteringQuickCraftCategories.remove(configuration.getCategoryIdentifier());
                        } else {
                            filteringQuickCraftCategories.put(configuration.getCategoryIdentifier(), false);
                        }
                    } else {
                        // set to true
                        if (quickCraftingEnabledByDefault) {
                            filteringQuickCraftCategories.remove(configuration.getCategoryIdentifier());
                        } else {
                            filteringQuickCraftCategories.put(configuration.getCategoryIdentifier(), true);
                        }
                    }

                    editedSink.run();
                }).leftAligned();
            }
            {
                this.upButton = new Button.Plain(0, 0, 20, 20, Component.literal("↑"), button -> {
                    int index = categoryOrdering.indexOf(configuration.getCategoryIdentifier());
                    if (index > 0) {
                        categoryOrdering.remove(index);
                        categoryOrdering.add(index - 1, configuration.getCategoryIdentifier());
                        editedSink.run();
                        resetListEntries();
                    }
                }, Supplier::get) {};
                this.downButton = new Button.Plain(0, 0, 20, 20, Component.literal("↓"), button -> {
                    int index = categoryOrdering.indexOf(configuration.getCategoryIdentifier());
                    if (index < categoryOrdering.size() - 1) {
                        categoryOrdering.remove(index);
                        categoryOrdering.add(index + 1, configuration.getCategoryIdentifier());
                        editedSink.run();
                        resetListEntries();
                    }
                }, Supplier::get) {};
                this.upButton.active = categoryOrdering.indexOf(configuration.getCategoryIdentifier()) > 0;
                this.downButton.active = categoryOrdering.indexOf(configuration.getCategoryIdentifier()) < categoryOrdering.size() - 1;
            }
        }

