@OnlyIn(Dist.CLIENT)
	public static void addPotionTooltip(FluidStack fs, Consumer<Component> tooltipAdder, float durationFactor) {
		PotionContents contents = fs.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY);
		Iterable<MobEffectInstance> effects = contents.getAllEffects();

		List<Pair<Holder<Attribute>, AttributeModifier>> list = Lists.newArrayList();

		boolean flag = true;
		for (MobEffectInstance mobeffectinstance : effects) {
			flag = false;
			MutableComponent mutablecomponent = Component.translatable(mobeffectinstance.getDescriptionId());
			Holder<MobEffect> holder = mobeffectinstance.getEffect();
			holder.value().createModifiers(mobeffectinstance.getAmplifier(),
				(h, m) -> list.add(Pair.of(h, m)));
			if (mobeffectinstance.getAmplifier() > 0) {
				mutablecomponent.append(" ")
					.append(Component.translatable("potion.potency." + mobeffectinstance.getAmplifier()).getString());
			}

			if (!mobeffectinstance.endsWithin(20)) {
				mutablecomponent.append(" (")
					.append(MobEffectUtil.formatDuration(mobeffectinstance, durationFactor, Minecraft.getInstance().level.tickRateManager().tickrate()))
					.append(")");
			}

			tooltipAdder.accept(mutablecomponent.withStyle(holder.value().getCategory().getTooltipFormatting()));
		}

		if (flag)
			tooltipAdder.accept(NO_EFFECT);

		if (!list.isEmpty()) {
			tooltipAdder.accept(CommonComponents.EMPTY);
			tooltipAdder.accept((Component.translatable("potion.whenDrank")).withStyle(ChatFormatting.DARK_PURPLE));

			for (Pair<Holder<Attribute>, AttributeModifier> pair : list) {
				AttributeModifier attributemodifier = pair.getSecond();
				double d1 = attributemodifier.amount();
				double d0;
				if (attributemodifier.operation() != AttributeModifier.Operation.ADD_MULTIPLIED_BASE
					&& attributemodifier.operation() != AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL) {
					d0 = attributemodifier.amount();
				} else {
					d0 = attributemodifier.amount() * 100.0D;
				}

				if (d1 > 0.0D) {
					tooltipAdder.accept((Component.translatable(
						"attribute.modifier.plus." + attributemodifier.operation().id(),
						ItemAttributeModifiers.ATTRIBUTE_MODIFIER_FORMAT.format(d0),
						Component.translatable(pair.getFirst().value().getDescriptionId())))
						.withStyle(ChatFormatting.BLUE));
				} else if (d1 < 0.0D) {
					d0 = d0 * -1.0D;
					tooltipAdder.accept((Component.translatable(
						"attribute.modifier.take." + attributemodifier.operation().id(),
						ItemAttributeModifiers.ATTRIBUTE_MODIFIER_FORMAT.format(d0),
						Component.translatable(pair.getFirst().value().getDescriptionId())))
						.withStyle(ChatFormatting.RED));
				}
			}
		}
	}

@OnlyIn(Dist.CLIENT)
    @Override
    public void drawHUD(ItemStack item, GuiGraphics guiGraphics) {
        addCapacityHUD(item, this.HUD);
        IElectricItem cont = GTCapabilityHelper.getElectricItem(item);
        if (cont == null) return;
        if (!cont.canUse(energyPerUse)) return;
        CompoundTag data = item.getTag();
        if (data != null) {
            if (data.contains("enabled")) {
                Component status = (data.getBoolean("enabled") ?
                        Component.translatable("metaarmor.hud.status.enabled") :
                        Component.translatable("metaarmor.hud.status.disabled"));
                Component result = Component.translatable("metaarmor.hud.engine_enabled", status);
                this.HUD.newString(result);
            }
            if (data.contains("canShare")) {
                String status = data.getBoolean("canShare") ? "metaarmor.hud.status.enabled" :
                        "metaarmor.hud.status.disabled";
                this.HUD.newString(Component.translatable("mataarmor.hud.supply_mode", Component.translatable(status)));
            }

            if (data.contains("hover")) {
                String status = data.getBoolean("hover") ? "metaarmor.hud.status.enabled" :
                        "metaarmor.hud.status.disabled";
                this.HUD.newString(Component.translatable("metaarmor.hud.hover_mode", Component.translatable(status)));
            }
        }
        this.HUD.draw(guiGraphics);
        this.HUD.reset();
    }

@Override
  public void createRecipeExtras(IRecipeExtrasBuilder builder, IDisplayableMeltingRecipe recipe, IFocusGroup focuses) {
    IRecipeSlotDrawable fluid = null;
    if (recipe.isTimeDynamic() || recipe.isTemperatureDynamic()) {
      fluid = CategoryUtil.findSlot(builder.getRecipeSlots().getSlots(), FLUID_SLOT);
    }

    // includes both the static arrow background and animated foreground
    int time = recipe.getTime();
    IDrawableWidget arrow = builder.addAnimatedRecipeArrowWidget(time * 5).setPosition(56, 18);
    // add time as a tooltip on the arrow
    if (recipe.isTimeDynamic() && fluid != null) {
      arrow.setTooltip(new MeltingArrowTooltip(recipe, fluid));
    } else {
      // not dynamic or fail to find the slot? static tooltip is fine
      arrow.setTooltip(Component.translatable(KEY_COOLING_TIME, time / 4));
    }

    if (recipe.getOreType() != null) {
      builder.addDrawableWidget(plus).setPosition(83, 26).setTooltip(TOOLTIP_ORE);
    }
    // draw temperature above the recipe, animated if requested
    if (recipe.isTemperatureDynamic() && fluid != null) {
      builder.addWidget(new TemperatureWidget(new ScreenPosition(0, 3), 113, recipe, fluid, Minecraft.getInstance().font));
    } else {
      builder.addText(Component.translatable(KEY_TEMPERATURE, recipe.getTemperature()), 113, 9)
        .setPosition(0, 3)
        .setColor(Color.GRAY.getRGB())
        .setTextAlignment(HorizontalAlignment.CENTER);
    }
  }

