@Override
	protected void renderTooltip(GuiGraphics guiGraphics, int x, int y)
	{
		if(!this.menu.getCarried().isEmpty())
			return;
		if(this.hoveredSlot instanceof IESlot.ItemHandlerGhost ghostSlot&&ghostSlot.hasItem())
		{
			int side = ghostSlot.getSlotIndex()/SorterBlockEntity.FILTER_SLOTS_PER_SIDE;
			if(menu.filterMasks.get(Direction.from3DDataValue(side)).get().allowTags())
			{
				ItemStack item = ghostSlot.getItem();
				List<Component> tagTooltip = Lists.newArrayList();
				// Add name
				MutableComponent name = Component.empty().append(item.getHoverName()).withStyle(item.getRarity().getStyleModifier());
				if(item.has(DataComponents.CUSTOM_NAME))
					name.withStyle(ChatFormatting.ITALIC);
				tagTooltip.add(name);

				// Add tags
				List<ResourceLocation> available = FilterTag.getAvailableForItem(item);
				if(available.isEmpty())
					tagTooltip.add(Component.translatable(Lib.DESC_INFO+"filter.tag.none_available"));
				else
				{
					tagTooltip.add(Component.translatable(Lib.DESC_INFO+"filter.tag.selected_scroll"));
					Optional<ResourceLocation> selected = this.menu.selectedTags.get(ghostSlot.getSlotIndex()).get();
					available.forEach(location -> {
						boolean isSelected = selected.isPresent()&&selected.get().equals(location);
						FilterTag filterTag = FilterTag.deserialize(item, location);
						tagTooltip.add(Component.literal(isSelected?" -> ": " > ")
								.append(filterTag!=null?filterTag.getComponent(): Component.literal("ERROR: UNKNOWN TAG"))
								.withStyle(isSelected?ChatFormatting.GRAY: ChatFormatting.DARK_GRAY)
						);
					});
				}
				guiGraphics.renderTooltip(this.font, tagTooltip, item.getTooltipImage(), item, x, y);
				return;
			}
		}
		super.renderTooltip(guiGraphics, x, y);
	}

public boolean addToGoggleTooltip(List<Component> tooltip, boolean isPlayerSneaking, int boilerSize) {
		if (!isActive())
			return false;

		calcMinMaxForSize(boilerSize);

		CreateLang.translate("boiler.status", getHeatLevelTextComponent().withStyle(ChatFormatting.GREEN))
			.forGoggles(tooltip);
		CreateLang.builder().add(getSizeComponent(true, false)).forGoggles(tooltip, 1);
		CreateLang.builder().add(getWaterComponent(true, false)).forGoggles(tooltip, 1);
		CreateLang.builder().add(getHeatComponent(true, false)).forGoggles(tooltip, 1);

		if (attachedEngines == 0)
			return true;

		int boilerLevel = Math.min(activeHeat, Math.min(maxHeatForWater, maxHeatForSize));
		double totalSU = getEngineEfficiency(boilerSize) * 16 * Math.max(boilerLevel, attachedEngines)
			* BlockStressValues.getCapacity(AllBlocks.STEAM_ENGINE.get());

		tooltip.add(CommonComponents.EMPTY);

		if (attachedEngines > 0 && maxHeatForSize > 0 && maxHeatForWater == 0 && (passiveHeat ? 1 : activeHeat) > 0) {
			CreateLang.translate("boiler.water_input_rate")
				.style(ChatFormatting.GRAY)
				.forGoggles(tooltip);
			CreateLang.number(waterSupply)
				.style(ChatFormatting.BLUE)
				.add(CreateLang.translate("generic.unit.millibuckets"))
				.add(CreateLang.text(" / ")
					.style(ChatFormatting.GRAY))
				.add(CreateLang.translate("boiler.per_tick", CreateLang.number(waterSupplyPerLevel)
						.add(CreateLang.translate("generic.unit.millibuckets")))
					.style(ChatFormatting.DARK_GRAY))
				.forGoggles(tooltip, 1);
			return true;
		}

		CreateLang.translate("tooltip.capacityProvided")
			.style(ChatFormatting.GRAY)
			.forGoggles(tooltip);

		CreateLang.number(totalSU)
			.translate("generic.unit.stress")
			.style(ChatFormatting.AQUA)
			.space()
			.add((attachedEngines == 1 ? CreateLang.translate("boiler.via_one_engine")
				: CreateLang.translate("boiler.via_engines", attachedEngines)).style(ChatFormatting.DARK_GRAY))
			.forGoggles(tooltip, 1);

		return true;
	}

