private void verifyClientRecipes(Minecraft minecraft) {
		IConnectionToServer serverConnection = data.serverConnection();
		RecipeMap clientRecipes = Internal.getClientSyncedRecipes();
		boolean showWarning = jeiClientConfigs.getClientConfig().recipeSyncWarningEnabled().get();

		if (Internal.hasClientSyncedRecipes() && clientRecipes.values().isEmpty()) {
			String key = "jei.message.server.recipe.sync.error";
			if (showWarning) {
				writeChatMessage(minecraft, Component.translatable(key).withStyle(ChatFormatting.RED));
			}
			LOGGER.error(Translator.translateToLocal(key));
		} else if (Internal.hasClientFallbackRecipes()) {
			if (!serverConnection.isJeiOnServer() &&
				serverConnection.isSameModLoader()
			) {
				String key = "jei.message.server.recipe.sync.jei.missing";
				String serverBrand = ClientConnectionHelper.getServerBrand();
				if (showWarning) {
					writeChatMessage(minecraft, Component.translatable(key, serverBrand).withStyle(ChatFormatting.RED));
				}
				LOGGER.warn(Translator.translateToLocalFormatted(key, serverBrand));
			} else if (ClientConnectionHelper.hasServerBrand(VANILLA_SERVER_BRAND)) {
				String key = "jei.message.server.recipe.sync.vanilla";
				if (showWarning) {
					writeChatMessage(minecraft, Component.translatable(key).withStyle(ChatFormatting.YELLOW));
				}
				LOGGER.warn(Translator.translateToLocal(key));
			} else {
				String key = "jei.message.server.recipe.sync.unavailable";
				String serverBrand = ClientConnectionHelper.getServerBrand();
				if (showWarning) {
					writeChatMessage(minecraft, Component.translatable(key, serverBrand).withStyle(ChatFormatting.RED));
				}
				LOGGER.warn(Translator.translateToLocalFormatted(key, serverBrand));
			}
		}
	}

private void cleanRequiresLevel() {
        if (!(REIRuntime.getInstance().getPreviousContainerScreen() == null || Minecraft.getInstance().getConnection() == null)) {
            return;
        }

        for (OptionCategory category : this.categories) {
            for (OptionGroup group : category.getGroups()) {
                group.getOptions().replaceAll(option -> {
                    if (option.isRequiresLevel()) {
                        return new CompositeOption<>(option.getId(), option.getName(), option.getDescription(), i -> 0, (i, v) -> new Object())
                                .entry(value -> translatable("config.rei.texts.requires_level").withStyle(ChatFormatting.RED))
                                .defaultValue(() -> 1);
                    } else {
                        return option;
                    }
                });
            }
        }
    }

@Override
    public @Nullable SceneAnnotation getAnnotation(GuidebookLevel level, BlockState blockState,
            BlockHitResult blockHitResult) {
        var pos = blockHitResult.getBlockPos();
        var be = level.getBlockEntity(pos);
        if (!(be instanceof IPartHost partHost)) {
            return null;
        }

        var partResult = partHost.selectPartWorld(blockHitResult.getLocation());
        if (partResult != null) {
            var part = partResult.part;
            var facade = partResult.facade;
            AABB aabb = null;
            Component description = Component.empty();
            if (part != null) {
                aabb = getAABB(partResult.side, partResult.part::getBoxes);
                description = partResult.part.getPartItem().asItem().getDefaultInstance().getItemName();
            } else if (facade != null) {
                aabb = getAABB(partResult.side, bch -> partResult.facade.getBoxes(bch, false));
                description = GuiText.Facade.text(partResult.facade.getItem().getDefaultInstance().getItemName());
            }

            if (aabb != null) {
                var annotation = new InWorldBoxAnnotation(
                        new Vector3f(pos.getX() + (float) aabb.minX, pos.getY() + (float) aabb.minY,
                                pos.getZ() + (float) aabb.minZ),
                        new Vector3f(pos.getX() + (float) aabb.maxX, pos.getY() + (float) aabb.maxY,
                                pos.getZ() + (float) aabb.maxZ),
                        SymbolicColor.IN_WORLD_BLOCK_HIGHLIGHT);
                annotation.setTooltipContent(description);
                return annotation;
            }
        }
        return null;
    }

