@Override
  @Nullable
  protected Component getVariantText(IDisplayModifierRecipe recipe) {
    Component variant = recipe.getVariant();
    if (variant != null) {
      return variant;
    }
    IntRange level = recipe.getLevel();
    int min = level.min();
    int max = level.max();
    // min being 1 means we only have a max level, we check this first as Max Level is better than exact typically
    if (min == 1) {
      if (max < ModifierEntry.VALID_LEVEL.max()) {
        return Component.translatable(KEY_MAX, max);
      }
    } else if (min == max) {
      return Component.translatable(KEY_EXACT, min);
    } else if (max == ModifierEntry.VALID_LEVEL.max()) {
      return Component.translatable(KEY_MIN, min);
    } else {
      return Component.translatable(KEY_RANGE, min, max);
    }
    return null;
  }

public void showTranslators() {
		if (showTranslators) {
			return;
		}
		showTranslators = true;
		if (!JadeUI.hasTranslation("gui.jade.translators") || "placeholder ".equals(I18n.get("gui.jade.translated_by", ""))) {
			return;
		}
		String s = I18n.get("gui.jade.translators");
		if ("Bob, Alice, Charlie".equals(s)) {
			return;
		}
		translators = Stream.of(StringUtils.split(s, ',')).map(String::trim).filter(StringUtils::isNotEmpty).toList();
		if (translators.size() > 1) {
			translatorIndex = RandomSource.create().nextInt(translators.size());
		}
		nextTranslator();
	}

