@Nullable
  @Override
  public IRecipeTransferError transferRecipe(ToolContainerMenu container, CraftingRecipe recipe, IRecipeSlotsView recipeSlotsView, Player player, boolean maxTransfer, boolean doTransfer) {
    // if we have no crafting slots, nothing to do
    int slots = container.getToolInventoryStart() - 1;
    if (slots <= 0) {
      return handlerHelper.createInternalError();
    }
    // must have server support
    if (!handlerHelper.recipeTransferHasServerSupport()) {
      Component tooltipMessage = Component.translatable("jei.tooltip.error.recipe.transfer.no.server");
      return handlerHelper.createUserErrorWithTooltip(tooltipMessage);
    }

    // if we have a full crafting grid, just do the normal transfer
    if (slots >= 9) {
      return handler.transferRecipe(container, recipe, recipeSlotsView, player, maxTransfer, doTransfer);
    }

    // if we have a small grid, recipe must fit in the 2x2
    List<IRecipeSlotView> slotViews = recipeSlotsView.getSlotViews(RecipeIngredientRole.INPUT);
    if (!validateIngredientsOutsidePlayerGridAreEmpty(slotViews)) {
      Component tooltipMessage = Component.translatable(
        "jei.tooltip.error.recipe.transfer.too.large.player.inventory"
      );
      return this.handlerHelper.createUserErrorWithTooltip(tooltipMessage);
    }

    // filter the crafting table input slots to player inventory input slots
    List<IRecipeSlotView> filteredSlotViews = filterSlots(slotViews);
    IRecipeSlotsView filteredRecipeSlots = this.handlerHelper.createRecipeSlotsView(filteredSlotViews);
    return this.handler.transferRecipe(container, recipe, filteredRecipeSlots, player, maxTransfer, doTransfer);
  }

@Override
	public OptionsList createOptions(OptionsList options) {
		options.setDisplayMode(IWailaConfig.get().accessibility().getAlwaysListMode() ?
				OptionsList.DisplayMode.LIST :
				OptionsList.DisplayMode.CARD);
		JadeClient.registerBuiltInVariables(options.builtInVariables());
		boolean noteServerFeature = Objects.requireNonNull(minecraft).level == null || IWailaConfig.get().general().isDebug() ||
				!WailaClientRegistration.instance().isServerConnected();
		BiConsumer<Identifier, Object> setter = (key, value) -> {
			IWailaConfig.get().plugin().set(key, value);
			options.updateOptionValue(key);
		};
		WailaClientRegistration.instance().getConfigListView(IWailaConfig.get().accessibility().getEnableAccessibilityPlugin()).forEach(
				category -> {
					options.add(new OptionsList.Title(category.title()));
					MutableObject<@Nullable OptionValue<?>> lastPrimary = new MutableObject<>();
					category.entries().forEach(entry -> {
						OptionValue<?> option = entry.createUI(
								options,
								"plugin_" + entry.id().toLanguageKey(),
								IWailaConfig.get().plugin(),
								setter);
						option.setId(entry.id());
						option.setIcon(entry.icon());
						if (entry.isSynced()) {
							option.setDisabled(true);
							option.appendDescription(Component.translatable("gui.jade.forced_plugin_config")
									.withStyle(ChatFormatting.DARK_RED));
						} else if (noteServerFeature && !WailaClientRegistration.instance().isClientFeature(entry.id())) {
							option.setServerFeature();
						}
						if (!IPluginConfig.isPrimaryKey(entry.id())) {
							OptionsList.Entry primary = lastPrimary.get();
							if (primary != null) {
								option.setSecondary(true);
								option.parent(primary);
							}
						} else {
							lastPrimary.setValue(option);
						}
					});
				});
		return options;
	}

private static void renderBlockInfo(GuiGraphics gui, BlockHitResult hitResult, Minecraft mc, Level level) {
			BlockPos pos = hitResult.getBlockPos();
			BlockState state = level.getBlockState(pos);

			ItemStack dispStack;
			MutableComponent text;

			if (state.hasProperty(BlockStateProperties.POWER)) {
				// redstone wire, sculk sensors, daylight detector, target block, weighted pressure plates
				dispStack = new ItemStack(state.getBlock());
				text = Component.literal(state.getValue(BlockStateProperties.POWER).toString())
						.withStyle(ChatFormatting.RED);
			} else if (state.is(Blocks.REPEATER)) {
				dispStack = new ItemStack(Blocks.REPEATER);
				text = Component.translatable("botaniamisc.monocle.repeater.delay",
						LocaleHelper.formatAsDecimalFraction(0.1f * state.getValue(RepeaterBlock.DELAY), 1));
			} else if (state.is(Blocks.COMPARATOR)) {
				dispStack = new ItemStack(Blocks.COMPARATOR);
				text = Component.translatable("botaniamisc.monocle.comparator."
						+ state.getValue(ComparatorBlock.MODE).getSerializedName());
			} else {
				return;
			}

			int x = mc.getWindow().getGuiScaledWidth() / 2 + 15;
			int y = mc.getWindow().getGuiScaledHeight() / 2 - 8;

			int textWidth = mc.font.width(text.getVisualOrderText());
			RenderHelper.renderHUDBox(gui, x - 4, y - 4, x + textWidth + 24, y + 20);
			gui.renderItem(dispStack, x, y);
			gui.drawString(mc.font, text, x + 20, y + 4, 0xFFFFFF);
		}

