			int itemX = x + 9;
			int itemY = y + windowHeight - 24;
			AllGuiTextures.FROGPORT_SLOT.render(graphics, itemX - 1, itemY - 1);
			graphics.renderItem(asStack, itemX, itemY);

			if (mouseX >= itemX && mouseX < itemX + 16 && mouseY >= itemY && mouseY < itemY + 16) {
				List<Component> linkTip = List.of(CreateLang.translate("gui.factory_panel.has_link_connections")
					.color(ScrollInput.HEADER_RGB)
					.component(),
					CreateLang.translate("gui.factory_panel.left_click_disconnect")
						.style(ChatFormatting.DARK_GRAY)
						.style(ChatFormatting.ITALIC)
						.component());
				graphics.renderComponentTooltip(font, linkTip, mouseX, mouseY);
			}
		}

		// PROMISES
		int state = promiseExpiration.getState();
		graphics.drawString(font, CreateLang.text(state == -1 ? " /" : state == 0 ? "30s" : state + "m")
			.component(), promiseExpiration.getX() + 3, promiseExpiration.getY() + 4, 0xffeeeeee, true);

		ItemStack asStack = PackageStyles.getDefaultBox();
		int itemX = x + 68;
		int itemY = y + windowHeight - 24;
		graphics.renderItem(asStack, itemX, itemY);
		int promised = behaviour.getPromised();
		graphics.renderItemDecorations(font, asStack, itemX, itemY, promised + "");

		if (mouseX >= itemX && mouseX < itemX + 16 && mouseY >= itemY && mouseY < itemY + 16) {
			List<Component> promiseTip = List.of();

			if (promised == 0) {
				promiseTip = List.of(CreateLang.translate("gui.factory_panel.no_open_promises")
					.color(ScrollInput.HEADER_RGB)
					.component(),
					CreateLang
						.translate(restocker ? "gui.factory_panel.restocker_promises_tip"
							: "gui.factory_panel.recipe_promises_tip")
						.style(ChatFormatting.GRAY)
						.component(),
					CreateLang
						.translate(restocker ? "gui.factory_panel.restocker_promises_tip_1"
							: "gui.factory_panel.recipe_promises_tip_1")
						.style(ChatFormatting.GRAY)
						.component(),
					CreateLang.translate("gui.factory_panel.promise_prevents_oversending")
						.style(ChatFormatting.GRAY)
						.component());
			} else {
				promiseTip = List.of(CreateLang.translate("gui.factory_panel.promised_items")
					.color(ScrollInput.HEADER_RGB)
					.component(),
					CreateLang.text(behaviour.getFilter()
						.getHoverName()
						.getString() + " x" + promised)
						.component(),
					CreateLang.translate("gui.factory_panel.left_click_reset")
						.style(ChatFormatting.DARK_GRAY)
						.style(ChatFormatting.ITALIC)
						.component());
			}

			graphics.renderComponentTooltip(font, promiseTip, mouseX, mouseY);
		}

		ms.popPose();
	}

@Override
    public List<IWidget> getWidgetsForDisplay(PanelSyncManager syncManager) {
        List<IWidget> widgets = new ArrayList<>();

        GenericListSyncHandler<Component> veinMaterialList = new GenericListSyncHandler.Builder<Component>()
                .adapter(ByteBufAdapters.COMPONENT)
                .getter(() -> {
                    var materials = getRecipeLogic().getVeinMaterials();
                    if (materials == null) return List.of();
                    return materials.stream()
                            .map(m -> (Component) m.material().getLocalizedName().withStyle(ChatFormatting.GREEN))
                            .toList();
                })
                .build();

        DynamicLinkedSyncHandler<GenericListSyncHandler<Component>> materialListWidgetHandler = new DynamicLinkedSyncHandler<>(
                veinMaterialList)
                .widgetProvider((psm, list) -> {
                    var listWidget = new ListWidget<>()
                            .widthRel(1)
                            .childSeparator(Icon.EMPTY_2PX);
                    var values = list.getValue();
                    if (values.isEmpty()) {
                        listWidget.child(Text.lang("gtceu.multiblock.ore_rig.drilled_ore_entry",
                                Component.translatable("gtceu.multiblock.fluid_rig.no_fluid_in_area")
                                        .withStyle(ChatFormatting.RED))
                                .asWidget());
                    }
                    for (var value : values) {
                        listWidget.child(Text.lang("gtceu.multiblock.ore_rig.drilled_ore_entry", value).asWidget());
                    }
                    return listWidget;
                });

        IntSyncValue oreAmount = new IntSyncValue(() -> getRecipeLogic().getOreToProduce());

        syncManager.syncValue("veinMaterials", veinMaterialList);
        syncManager.syncValue("oreAmount", oreAmount);

        widgets.add(GTMultiblockTextUtil.addUnformedWarning(this, syncManager));
        widgets.add(GTMultiblockTextUtil.addEnergyTierLine(this, syncManager));

        widgets.add(Text.dynamic(() -> Component.translatable("gtceu.multiblock.ore_rig.ore_amount",
                Component.literal(FormattingUtil.formatNumbers(
                        getRecipeLogic().getOreToProduce() * 20L / BedrockOreMinerLogic.MAX_PROGRESS) + "/s")
                        .withStyle(ChatFormatting.BLUE)))
                .asWidget());

        widgets.add(Text.lang("gtceu.multiblock.ore_rig.drilled_ores_list").asWidget());

        widgets.add(new DynamicWidget<>().syncHandler(materialListWidgetHandler));

        return widgets;
    }

@Override
  public void updateDisplay() {
    if (this.tile == null) {
      return;
    }

    // fetch the tool version of the result for the screen
    LazyToolStack lazyResult = tile.getResult();

    // if we have a message, display instead of refreshing the tool
    Component currentError = tile.getCurrentError();
    if (currentError != null) {
      error(currentError);
      return;
    }

    // only get to rename new tool in the station
    // anvil can rename on any tool change
    if (lazyResult == null || (tile.getInputCount() <= 4 && this.getMenu().getSlot(TINKER_SLOT).hasItem())) {
      textField.setEditable(false);
      textField.setValue("");
      textField.visible = false;
    } else if (!textField.isEditable()) {
      textField.setEditable(true);
      textField.setValue("");
      textField.visible = true;
    } else {
      // ensure the text matches
      textField.setValue(tile.getItemName());
    }

    // if there is no result, use the input
    if (lazyResult == null) {
      lazyResult = tile.getTool();
    }
    updateArmorStandPreview(lazyResult.getStack());

    // if the contained stack is modifiable, display some information
    if (lazyResult.hasTag(TinkerTags.Items.MODIFIABLE)) {
      ToolStack tool = lazyResult.getTool();
      updateToolPanel(lazyResult);
      updateModifierPanel(tool);
    }
    // tool build info
    else {
      this.tinkerInfo.setCaption(this.currentLayout.getDisplayName());
      this.tinkerInfo.setText(this.currentLayout.getDescription());

      // for each named slot, color the slot if the slot is filled
      // typically all input slots should be named, or none of them
      MutableComponent fullText = Component.literal("");
      boolean hasComponents = false;
      for (int i = 0; i <= activeInputs; i++) {
        LayoutSlot layout = currentLayout.getSlot(i);
        String key = layout.getTranslationKey();
        if (!layout.isHidden() && !key.isEmpty()) {
          hasComponents = true;
          MutableComponent textComponent = Component.literal(" * ");
          ItemStack slotStack = this.getMenu().getSlot(i).getItem();
          if (!layout.isValid(slotStack)) {
            textComponent.withStyle(ChatFormatting.RED);
          }
          textComponent.append(Component.translatable(key)).append("\n");
          fullText.append(textComponent);
        }
      }
      // if we found any components, set the text, use the anvil if no components
      if (hasComponents) {
        this.modifierInfo.setCaption(COMPONENTS_TEXT);
        this.modifierInfo.setText(fullText);
      } else {
        this.modifierInfo.setCaption(Component.empty());
        this.modifierInfo.setText(ASCII_ANVIL);
      }
    }
  }

