public static Optional<Widget<?>> createFluidLineForOutput(Content fluidOutput, GTRecipe recipe) {
        int runs = recipe.getTotalRuns();

        double maxDurationSec = (double) recipe.duration / 20.0;

        boolean rounded = false;
        FluidStack stack;
        // amount of fluid output by a non-ranged ingredient
        int amount = 0;
        // amount of fluid output, but stored as a double. Used for accurate fluid/second display.
        double amountD = 1;
        // amount of fluid output which is actually displayed. Can be either a number, or a range.
        Component displaycount;
        if (fluidOutput.content() instanceof IntProviderFluidIngredient provider) {
            rounded = true;
            stack = provider.getMaxSizeStack();
            displaycount = Component.translatable("gtceu.gui.content.range",
                    provider.getCountProvider().getMinValue(),
                    provider.getCountProvider().getMaxValue());
            if (fluidOutput.chance() < fluidOutput.maxChance()) {
                amountD = amountD * runs * fluidOutput.chance() / fluidOutput.maxChance();
            }
            amountD = amountD * provider.getMidRoll();
        } else {
            var stacks = FluidRecipeCapability.CAP.of(fluidOutput.content()).getStacks();
            if (stacks.length == 0) return Optional.empty();
            stack = stacks[0].copy();
            amount = stack.getAmount();
            amountD *= amount;
            if (fluidOutput.chance() < fluidOutput.maxChance()) {
                rounded = true;
                amountD = amountD * runs * fluidOutput.chance() / fluidOutput.maxChance();
            }
            amount = Math.max(1, (int) Math.round(amountD));
            stack.setAmount(amount);
            displaycount = Component.literal(String.valueOf(amount));
        }
        if (amountD < maxDurationSec) {
            String key = "gtceu.multiblock.output_line." + (rounded ? "2" : "0");
            return Optional.of(
                    Flow.row()
                            .coverChildrenHeight()
                            .childPadding(2)
                            .child(new FluidDrawable(stack).asWidget()
                                    .size(16)
                                    .tooltip(r -> r.add(stack.getDisplayName())))
                            .child(
                                    Text.lang(
                                            key, stack.getDisplayName(), displaycount,
                                            FormattingUtil.formatNumber2Places(maxDurationSec / amountD))
                                            .asWidget()));
        } else {
            String key = "gtceu.multiblock.output_line." + (rounded ? "3" : "1");
            return Optional.of(
                    Flow.row()
                            .coverChildrenHeight()
                            .childPadding(2)
                            .child(new FluidDrawable(stack).asWidget()
                                    .size(16)
                                    .tooltip(r -> r.add(stack.getDisplayName())))
                            .child(
                                    Text.lang(key, stack.getDisplayName(), displaycount,
                                            FormattingUtil.formatNumber2Places(amountD / maxDurationSec))
                                            .asWidget()));
        }
    }

@Override
    public void getTooltip(List<Component> tooltips) {
        if (ritual != null) {
            tooltips.add(Component.literal(ritual.getName()));
            if (isOff) {
                tooltips.add(Component.translatable("ars_nouveau.tooltip.turned_off").withStyle(ChatFormatting.GOLD));
                return;
            }
            if (!ritual.isRunning()) {
                if (!ritual.canStart(ArsNouveau.proxy.getPlayer())) {
                    tooltips.add(Component.translatable("ars_nouveau.tooltip.conditions_unmet").withStyle(ChatFormatting.GOLD));
                } else
                    tooltips.add(Component.translatable("ars_nouveau.tooltip.waiting").withStyle(ChatFormatting.GOLD));
            } else {

                tooltips.add(Component.translatable("ars_nouveau.tooltip.running"));
            }
            if (!ritual.getConsumedItems().isEmpty()) {
                tooltips.add(Component.translatable("ars_nouveau.tooltip.consumed"));
                for (String i : ritual.getFormattedConsumedItems()) {
                    tooltips.add(Component.literal(i));
                }
            }
            if (ritual.needsSourceNow())
                tooltips.add(Component.translatable("ars_nouveau.wixie.need_mana").withStyle(ChatFormatting.GOLD));

            ritual.modifyTooltips(tooltips);
        }
    }

