@Override
    public @NotNull Result onMousePressed(int button) {
        var mouseX = getContext().getMouseX();
        var mouseY = getContext().getMouseY();

        if (!WaypointManager.isActive()) return Result.IGNORE;

        WaypointItem clickedItem = getClickedVein(mouseX, mouseY);
        if (clickedItem == null) return Result.ACCEPT;

        WaypointManager.setWaypoint(clickedItem.uniqueId,
                clickedItem.name.getString(), clickedItem.color,
                player.level().dimension(), clickedItem.position);
        player.displayClientMessage(
                Component.translatable("behavior.prospector.added_waypoint",
                        clickedItem.name.copy().withStyle(style -> style.withColor(clickedItem.color))),
                false);
        this.getContext().getScreen().getMainPanel().closeIfOpen();

        Interactable.playButtonClickSound();
        return Result.SUCCESS;
    }

public void setRecipe(RecipeHolder<GlyphRecipe> recipe, Player player) {
        if (ScribesTile.getTotalPlayerExperience(player) < recipe.value().exp && !player.isCreative()) {
            PortUtil.sendMessage(player, Component.translatable("ars_nouveau.not_enough_exp").withStyle(ChatFormatting.GOLD));
            return;
        } else if (!player.isCreative()) {
            player.giveExperiencePoints(-recipe.value().exp);
        }
        ScribesTile tile = getLogicTile();
        if (tile == null)
            return;
        tile.refundConsumed();
        tile.recipe = recipe;
        tile.recipeID = recipe.id();
        PortUtil.sendMessage(player, Component.translatable("ars_nouveau.scribes_table.started_crafting").withStyle(ChatFormatting.GOLD));
        tile.updateBlock();
    }

