@Override
    public void updateTooltip(int mouseX, int mouseY) {
        Registry<Upgrade> upgrades = upgradeRegistry.get();
        int size = upgrades == null ? 0 : upgrades.size();
        int relativeMouseX = mouseX - getX() - 1;
        int relativeMouseY = mouseY - getY() - 1;
        if (size > 0 && relativeMouseX >= 0 && relativeMouseX < PADDED_ELEMENT_WIDTH && relativeMouseY >= 0 && relativeMouseY < ELEMENT_SIZE * (getRow(size - 1) + 1)) {
            int targetRow = relativeMouseY / ELEMENT_SIZE;
            int index;
            if (targetRow == 0) {
                relativeMouseX -= firstRowStart;
                index = relativeMouseX / ELEMENT_SIZE;
            } else {
                index = firstRowRoom + ROW_ROOM * (targetRow - 1) + relativeMouseX / ELEMENT_SIZE;
            }
            //Note: Registry#get returns an empty optional
            Reference<Upgrade> holder = upgrades.get(index).orElse(null);
            if (holder != null) {
                Upgrade upgrade = holder.value();
                Component upgradeName = MekanismLang.UPGRADE_TYPE.translateColored(EnumColor.YELLOW, upgrade);
                List<Component> info;
                if (holder.is(supportedUpgrades)) {
                    info = List.of(upgradeName, upgrade.description());
                } else {
                    info = List.of(MekanismLang.UPGRADE_NOT_SUPPORTED.translateColored(EnumColor.RED, upgradeName), upgrade.description());
                }
                if (!info.equals(lastInfo)) {
                    lastInfo = info;
                    lastTooltip = TooltipUtils.create(info);
                    UpgradePos pos = getUpgradePos(index);
                    //Note: We only have to update the tooltip rect if the tooltip changed as we know none of the elements share the same tooltips
                    cachedTooltipRect = new ScreenRectangle(getX() + 1 + pos.x, getY() + 1 + pos.y, ELEMENT_SIZE, ELEMENT_SIZE);
                }
                setTooltip(lastTooltip);
                //We can break once we managed to find a tooltip to render
                return;
            }
        }
        lastInfo = Collections.emptyList();
        cachedTooltipRect = null;
        setTooltip(lastTooltip = null);
    }

public static List<FavoriteMenuEntry> createInputMethodEntries(MenuAccess access, List<Map.Entry<Identifier, InputMethod<?>>> applicableInputMethods) {
        ConfigObjectImpl config = ConfigManagerImpl.getInstance().getConfig();
        List<FavoriteMenuEntry> entries = applicableInputMethods.stream()
                .<FavoriteMenuEntry>map(pair -> ToggleMenuEntry.of(pair.getValue().getName(),
                                () -> Objects.equals(config.getInputMethodId(), pair.getKey()),
                                bool -> {
                                    ExecutorService service = Executors.newSingleThreadExecutor();
                                    InputMethod<?> active = InputMethod.active();
                                    active.dispose(service).whenComplete((unused, throwable) -> {
                                        if (throwable != null) {
                                            InternalLogger.getInstance().error("Failed to dispose input method", throwable);
                                        }

                                        ConfigManagerImpl.getInstance().getConfig().setInputMethodId(Identifier.parse("rei:default"));
                                    }).join();
                                    double[] progress = {0};
                                    CompletableFuture<Void> future = pair.getValue().prepare(service, p -> progress[0] = Mth.clamp(p, 0, 1)).whenComplete((unused, throwable) -> {
                                        if (throwable != null) {
                                            InternalLogger.getInstance().error("Failed to prepare input method", throwable);
                                            ConfigManagerImpl.getInstance().getConfig().setInputMethodId(Identifier.parse("rei:default"));
                                        } else {
                                            ConfigManagerImpl.getInstance().getConfig().setInputMethodId(pair.getKey());
                                        }
                                    });
                                    Screen screen = Minecraft.getInstance().gui.screen();
                                    ConfigReloadingScreen reloadingScreen = new ConfigReloadingScreen(Component.translatable("text.rei.input.methods.initializing"),
                                            () -> !future.isDone(), () -> {
                                        Minecraft.getInstance().setScreenAndShow(screen);
                                    }, () -> {
                                        Minecraft.getInstance().setScreenAndShow(screen);
                                        InternalLogger.getInstance().error("Failed to prepare input method: cancelled");
                                        ConfigManagerImpl.getInstance().getConfig().setInputMethodId(Identifier.parse("rei:default"));
                                        future.cancel(Platform.isFabric());
                                        service.shutdown();
                                    });
                                    reloadingScreen.setSubtitle(() -> Component.translatable("text.rei.input.methods.reload.progress", String.format("%.2f", progress[0] * 100)));
                                    Minecraft.getInstance().setScreenAndShow(reloadingScreen);
                                    access.close();
                                    future.whenComplete((unused, throwable) -> {
                                        service.shutdown();
                                        if (throwable != null) return;
                                        ScreenOverlayImpl.getInstance().getHintsContainer().addHint(12, () -> new Point(getCraftableFilterBounds().getCenterX(), getCraftableFilterBounds().getCenterY()),
                                                "text.rei.hint.input.methods", List.of(Component.translatable("text.rei.hint.input.methods")));
                                    });
                                })
                        .withActive(() -> !Objects.equals(config.getInputMethodId(), pair.getKey()))
                        .withTooltip(() -> Tooltip.create(Widget.mouse(), pair.getValue().getDescription()))
                )
                .collect(Collectors.toList());
        InputMethod<?> active = InputMethod.active();
        if (!(active instanceof DefaultInputMethod)) {
            entries.add(0, new SeparatorMenuEntry());
            entries.add(0, FavoriteMenuEntry.createToggle(Component.translatable("text.rei.input.methods.tooltip.hints"), new BooleanValue() {
                @Override
                public void accept(boolean t) {
                    ConfigManagerImpl.getInstance().getConfig().setDoDisplayIMEHints(!getAsBoolean());
                }

                @Override
                public boolean getAsBoolean() {
                    return ConfigObject.getInstance().doDisplayIMEHints();
                }
            }));
        }
        List<FavoriteMenuEntry> optionsMenuEntries = active.getOptionsMenuEntries();
        if (!optionsMenuEntries.isEmpty()) {
            entries.add(new SeparatorMenuEntry());
            entries.addAll(optionsMenuEntries);
        }
        return entries;
    }

