			.forGoggles(tooltip);

		if (itemCapability == null)
			itemCapability = new ItemStackHandler();
		if (fluidCapability == null)
			fluidCapability = new FluidTank(0);

		boolean isEmpty = true;

		for (int i = 0; i < itemCapability.getSlots(); i++) {
