@Override
    public void updateTooltip(int mouseX, int mouseY) {
        ItemStack stack = gui().getCarriedItem();
        List<Component> list = Collections.emptyList();
        if (onHover != null) {
            list = onHover.apply(this);
        }
        if (list.isEmpty() && !stack.isEmpty() && stack.getItem() instanceof ItemConfigurator && gui() instanceof GuiMekanismTile<?, ?> gui &&
            gui.getTileEntity() instanceof ISideConfiguration config && gui.getHoveredSlot() instanceof InventoryContainerSlot slot) {
            ConfigInfo info = config.getConfig().getConfig(TransmissionType.ITEM);
            if (info != null) {
                IInventorySlot inventorySlot = slot.getInventorySlot();
                for (DataType type : info.getSupportedDataTypes()) {
                    if (info.getSlotInfo(type) instanceof InventorySlotInfo slotInfo && slotInfo.hasSlot(inventorySlot)) {
                        EnumColor color = type.getColor();
                        list = List.of(MekanismLang.GENERIC_WITH_PARENTHESIS.translateColored(color, type, color.getName()));
                        break;
                    }
                }
            }
        }
        if (!list.equals(lastInfo)) {
            lastInfo = list;
            lastTooltip = TooltipUtils.create(list);
        }
        setTooltip(lastTooltip);
    }

public static List<Widget> getCategoryButtons(Rectangle bounds, boolean isCompactTabButtons, int tabSize, int tabButtonsSize,
                                                  Runnable leftAction, Runnable rightAction) {
        List<Widget> widgets = new ArrayList<>();
        Button tabLeft, tabRight;
        widgets.add(tabLeft = Widgets.createButton(new Rectangle(bounds.x, bounds.getMaxY() - tabSize + 1 - tabButtonsSize, tabButtonsSize, tabButtonsSize), Component.literal(""))
                .onClick(button -> leftAction.run())
                .tooltipLine(Component.translatable("text.rei.previous_page")));
        widgets.add(tabRight = Widgets.createButton(new Rectangle(bounds.x + bounds.width - tabButtonsSize - (isCompactTabButtons ? 0 : 1), bounds.getMaxY() - tabSize + 1 - tabButtonsSize, tabButtonsSize, tabButtonsSize), Component.literal(""))
                .onClick(button -> rightAction.run())
                .tooltipLine(Component.translatable("text.rei.next_page")));

        widgets.add(Widgets.createDrawableWidget((graphics, mouseX, mouseY, delta) -> {
            Rectangle tabLeftBounds = tabLeft.getBounds();
            Rectangle tabRightBounds = tabRight.getBounds();
            if (isCompactTabButtons) {
                graphics.pose().pushMatrix();
                graphics.pose().translate(0, 0.5f);
                graphics.blit(RenderPipelines.GUI_TEXTURED, InternalTextures.ARROW_LEFT_SMALL_TEXTURE, tabLeftBounds.x + 2, tabLeftBounds.y + 2, 0, 0, 6, 6, 6, 6);
                graphics.blit(RenderPipelines.GUI_TEXTURED, InternalTextures.ARROW_RIGHT_SMALL_TEXTURE, tabRightBounds.x + 2, tabRightBounds.y + 2, 0, 0, 6, 6, 6, 6);
                graphics.pose().popMatrix();
            } else {
                graphics.blit(RenderPipelines.GUI_TEXTURED, InternalTextures.ARROW_LEFT_TEXTURE, tabLeftBounds.x + 4, tabLeftBounds.y + 4, 0, 0, 8, 8, 8, 8);
                graphics.blit(RenderPipelines.GUI_TEXTURED, InternalTextures.ARROW_RIGHT_TEXTURE, tabRightBounds.x + 4, tabRightBounds.y + 4, 0, 0, 8, 8, 8, 8);
            }
        }));
        return widgets;
    }

