@Override
    public void render(GuiGraphics graphics, int mouseX, int mouseY, float delta) {
        if (!hasSpace()) return;

        renderEntries(graphics, mouseX, mouseY, delta);

        debugger.render(graphics, bounds.x, bounds.y, delta);

        if (containsChecked(mouseX, mouseY, false) && ClientHelper.getInstance().isCheating() && !(Minecraft.getInstance().gui.screen() instanceof DisplayScreen) && !minecraft.player.containerMenu.getCarried().isEmpty() && ClientHelperImpl.getInstance().canDeleteItems()) {
            EntryStack<?> stack = EntryStacks.of(minecraft.player.containerMenu.getCarried().copy());
            if (stack.getType() != VanillaEntryTypes.ITEM) {
                EntryStack<ItemStack> cheatsAs = stack.cheatsAs();
                stack = cheatsAs.isEmpty() ? stack : cheatsAs;
            }
            for (Widget child : children()) {
                if (child.containsMouse(mouseX, mouseY) && child instanceof EntryWidget widget) {
                    if (widget.cancelDeleteItems(stack)) {
                        return;
                    }
                }
            }
            Tooltip.create(Component.translatable("text.rei.delete_items")).queue();
        }

        scaleIndicator.update(delta);
        if (scaleIndicator.value() > 0.04) {
            Component component = Component.literal(Math.round(ConfigObject.getInstance().getEntrySize() * 100) + "%");
            int width = font.width(component);
            int backgroundColor = ((int) Math.round(0xa0 * Mth.clamp(scaleIndicator.value(), 0.0, 1.0))) << 24;
            int textColor = ((int) Math.round(0xdd * Mth.clamp(scaleIndicator.value(), 0.0, 1.0))) << 24;
            graphics.fillGradient(bounds.getCenterX() - width / 2 - 2, bounds.getCenterY() - 6, bounds.getCenterX() + width / 2 + 2, bounds.getCenterY() + 6, backgroundColor, backgroundColor);
            graphics.drawString(font, component, bounds.getCenterX() - width / 2, bounds.getCenterY() - 4, 0xFFFFFF | textColor, false);
        }
    }

private void initGathererSourceSubOptions(int i) {
		DisplaySource source = sources.get(i);
		source.populateData(new DisplayLinkContext(blockEntity.getLevel(), blockEntity));

		if (targetLineSelector != null)
			targetLineSelector
				.titled(source instanceof SingleLineDisplaySource ? CreateLang.translateDirect("display_link.display_on")
					: CreateLang.translateDirect("display_link.display_on_multiline"));

		configWidgets.forEach(s -> {
			s.forEach(this::removeWidget);
			s.clear();
		});

		DisplayLinkContext context = new DisplayLinkContext(minecraft.level, blockEntity);
		configWidgets.forEachWithContext((s, first) -> source.initConfigurationWidgets(context,
			new ModularGuiLineBuilder(font, s, guiLeft + 60, guiTop + (first ? 51 : 72)), first));
		configWidgets
			.forEach(s -> s.loadValues(blockEntity.getSourceConfig(), this::addRenderableWidget, this::addRenderableOnly));
	}

@Override
    protected void addTooltip(CompoundTag data, ITooltip tooltip, Player player, BlockAccessor block,
                              BlockEntity blockEntity, IPluginConfig config) {
        CompoundTag container = data.getCompound("energy");
        long changed = container.getLong("changed"), stored = container.getLong("stored"),
                capacity = container.getLong("capacity");
        tooltip.add(Component.translatable("gtceu.jade.changes_eu_tick",
                FormattingUtil.formatNumbers(((double) changed) / 20.0)));
        if (changed > 0L) {
            tooltip.add(Component
                    .translatable("gtceu.jade.remaining_charge_time",
                            getStringRemainTime((capacity - stored) / changed)));
        } else if (changed < 0L) {
            tooltip.add(Component.translatable("gtceu.jade.remaining_discharge_time",
                    getStringRemainTime((stored) / -changed)));
        }
        if (GTUtil.isShiftDown()) {
            CustomItemStackHandler handler = new CustomItemStackHandler();
            handler.deserializeNBT(data.getCompound("storage"));
            IElementHelper helper = tooltip.getElementHelper();
            for (int i = 0; i < handler.getSlots(); i++) {
                if (handler.getStackInSlot(i).getCount() != 0) {
                    ItemStack stack = handler.getStackInSlot(i);
                    tooltip.add(helper.smallItem(stack));
                    IElectricItem item = GTCapabilityHelper.getElectricItem(stack);
                    if (item == null) continue;
                    tooltip.append(Component.literal(
                            GTValues.VNF[item.getTier()] + "§r " + formatLongNumber(item.getCharge()) +
                                    " / " + formatLongNumber(item.getMaxCharge()) + " EU"));
                }
            }
        }
    }

@Override
    public void appendHoverText(@NotNull ItemStack stack, @NotNull TooltipContext world, @NotNull List<Component> tooltip, @NotNull TooltipFlag p_77624_4_) {
        DominionWandData data = stack.getOrDefault(DataComponentRegistry.DOMINION_WAND, new DominionWandData());
        if (data.storedEntityId() == DominionWandData.NULL_ENTITY) {
            tooltip.addAll(DocClientUtils.splitTooltip(Component.translatable("ars_nouveau.dominion_wand.no_entity"), world));
        } else {
            tooltip.addAll(DocClientUtils.splitTooltip(Component.translatable("ars_nouveau.dominion_wand.entity_stored"), world));
        }

        if (data.storedPos().isEmpty()) {
            tooltip.addAll(DocClientUtils.splitTooltip(Component.translatable("ars_nouveau.dominion_wand.no_location"), world));
        } else {
            tooltip.addAll(DocClientUtils.splitTooltip(Component.translatable("ars_nouveau.dominion_wand.position_stored", getGlobalPosString(data.getValidPos())), world));
        }

        if (data.strict()) tooltip.addAll(DocClientUtils.splitTooltip(Component.literal("Side-Sensitive"), world));
    }

